python3 - <<'PY'
import subprocess, time, socket, urllib.request, urllib.error, os, signal
def start(args,cwd="/tmp/docroot"):
    p=subprocess.Popen(["/workspace/executable"]+args, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, cwd=cwd)
    time.sleep(0.7)
    return p
def get(url, data=None, method=None, headers=None):
    try:
        req=urllib.request.Request(url,data=data,method=method,headers=headers or {})
        with urllib.request.urlopen(req,timeout=3) as r:
            return r.status, dict(r.headers), r.read()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read()
    except Exception as e:
        return None,{},str(e).encode()

for args,label in [(["-S","127.0.0.1:18099","-t","/tmp/docroot"],"docroot"), (["-S","127.0.0.1:18099","-t","/tmp/docroot","/tmp/router.php"],"router"), (["-S","127.0.0.1:18099"],"cwd")]:
    p=start(args)
    print("\n==",label,"poll",p.poll())
    for url in ["http://127.0.0.1:18099/","http://127.0.0.1:18099/index.php?a=1&b[]=2","http://127.0.0.1:18099/hello.txt","http://127.0.0.1:18099/sub/page.php","http://127.0.0.1:18099/nope","http://127.0.0.1:18099/nope.php","http://127.0.0.1:18099/sub/"]:
        print(url, get(url))
    print("POST", get("http://127.0.0.1:18099/index.php", data=b"x=10&y=20", method="POST", headers={"Content-Type":"application/x-www-form-urlencoded"}))
    p.terminate()
    try:
        out,_=p.communicate(timeout=3)
    except:
        p.kill(); out,_=p.communicate()
    print("LOG:",out[:3000].decode(errors="replace"))
PY"}

