import sys, json
data=open('/tmp/extract.ser','rb').read()
pos=0
refs=[]
def parse():
    global pos
    t=chr(data[pos]); pos+=1
    if t=='N':
        assert chr(data[pos])==';'; pos+=1; return None
    elif t=='b':
        assert chr(data[pos])==':'; pos+=1; v=data[pos:pos+1]; pos+=1; assert chr(data[pos])==';'; pos+=1; return v==b'1'
    elif t=='i':
        assert chr(data[pos])==':'; pos+=1; end=data.index(b';',pos); v=int(data[pos:end]); pos=end+1; return v
    elif t=='d':
        assert chr(data[pos])==':'; pos+=1; end=data.index(b';',pos); s=data[pos:end].decode(); pos=end+1
        if s=='INF': return float('inf')
        if s=='-INF': return float('-inf')
        if s=='NAN': return float('nan')
        return float(s)
    elif t=='s':
        assert chr(data[pos])==':'; pos+=1; end=data.index(b':',pos); ln=int(data[pos:end]); pos=end+1; assert chr(data[pos])=='"'; pos+=1; v=data[pos:pos+ln]; pos+=ln; assert chr(data[pos])=='"'; pos+=1; assert chr(data[pos])==';'; pos+=1
        try: return v.decode('utf-8')
        except: return {"__bytes__": v.hex()}
    elif t=='a':
        assert chr(data[pos])==':'; pos+=1; end=data.index(b':',pos); n=int(data[pos:end]); pos=end+1; assert chr(data[pos])=='{'; pos+=1
        # keep as list of [k,v] if not simple? We'll build dict if keys strings/ints unique, but PHP int keys become strings in JSON. Use special format list pairs.
        items=[]
        for _ in range(n):
            k=parse(); v=parse(); items.append([k,v])
        assert chr(data[pos])=='}'; pos+=1
        # decide: if keys are 0..n-1 sequential ints -> list
        if all(isinstance(k,int) for k,_ in items) and [k for k,_ in items]==list(range(n)):
            return [v for _,v in items]
        if all(isinstance(k,(str,int)) for k,_ in items):
            # dict with stringified keys but preserve int keys marking? use dict with str keys; caller knows
            d={}
            for k,v in items: d[str(k) if isinstance(k,int) else k]=v
            # if any int keys nonsequential, wrap
            if any(isinstance(k,int) for k,_ in items):
                return {"__php_array__": items}
            return d
        return {"__php_array__": items}
    elif t=='O':
        assert chr(data[pos])==':'; pos+=1; end=data.index(b':',pos); ln=int(data[pos:end]); pos=end+1; assert chr(data[pos])=='"'; pos+=1; cls=data[pos:pos+ln].decode(); pos+=ln; assert chr(data[pos])=='"'; pos+=1; assert chr(data[pos])==':'; pos+=1; end=data.index(b':',pos); n=int(data[pos:end]); pos=end+1; assert chr(data[pos])=='{'; pos+=1
        props=[]
        for _ in range(n):
            k=parse(); v=parse(); props.append([k,v])
        assert chr(data[pos])=='}'; pos+=1
        return {"__object__":cls,"props":props}
    elif t=='E':
        # enum  E:len:"Class:Case";
        assert chr(data[pos])==':'; pos+=1; end=data.index(b':',pos); ln=int(data[pos:end]); pos=end+1; assert chr(data[pos])=='"'; pos+=1; v=data[pos:pos+ln].decode(); pos+=ln; assert chr(data[pos])=='"'; pos+=1; assert chr(data[pos])==';'; pos+=1
        return {"__enum__":v}
    elif t in ('r','R'):
        assert chr(data[pos])==':'; pos+=1; end=data.index(b';',pos); v=int(data[pos:end]); pos=end+1; return {"__ref__":v}
    elif t=='C':
        # Serializable
        assert chr(data[pos])==':'; pos+=1; end=data.index(b':',pos); ln=int(data[pos:end]); pos=end+1; assert chr(data[pos])=='"'; pos+=1; cls=data[pos:pos+ln].decode(); pos+=ln; assert chr(data[pos])=='"'; pos+=1; assert chr(data[pos])==':'; pos+=1; end=data.index(b':',pos); ln2=int(data[pos:end]); pos=end+1; assert chr(data[pos])=='{'; pos+=1; payload=data[pos:pos+ln2]; pos+=ln2; assert chr(data[pos])=='}'; pos+=1
        return {"__serializable__":cls,"data":payload.decode(errors='replace')}
    else:
        raise Exception(f"unknown type {t} at {pos} ctx {data[pos-20:pos+50]}")

obj=parse()
print("parsed pos",pos,"len",len(data))
with open('/tmp/extract.json','w') as f: json.dump(obj,f)
