# Independently implemented PHP-compatible interpreter core.
# PHP strings are Python bytes, ints are Python ints, floats are Python floats,
# bool is Python bool, null is None, arrays are PhpArray, objects PhpObject.
import sys, os, re, math, time, threading, copy as _copy
from collections import OrderedDict

PHP_INT_MAX = 9223372036854775807
PHP_INT_MIN = -9223372036854775808

class _Uninit: 
    def __repr__(self): return 'UNINIT'
UNINIT = _Uninit()
class _Undef:
    def __repr__(self): return 'UNDEF'
UNDEF = _Undef()

def bstr(x):
    """Convert Python str/bytes to PHP string (bytes)."""
    if isinstance(x, bytes): return x
    if isinstance(x, bytearray): return bytes(x)
    if x is None: return b''
    return str(x).encode('utf-8', 'surrogateescape')

def sstr(x):
    """Convert PHP bytes to Python str preserving arbitrary bytes."""
    if isinstance(x, (bytes, bytearray)): return bytes(x).decode('utf-8', 'surrogateescape')
    if x is None: return ''
    return str(x)

def wrap64(n):
    n = int(n) & ((1<<64)-1)
    if n >= (1<<63): n -= (1<<64)
    return n

def int_overflow_float(n):
    if isinstance(n, int) and not isinstance(n, bool) and (n > PHP_INT_MAX or n < PHP_INT_MIN):
        return float(n)
    return n

class Cell:
    __slots__ = ('value', 'is_ref')
    def __init__(self, value=None, is_ref=False):
        self.value = value
        self.is_ref = is_ref
    def __repr__(self):
        return f'Cell({self.value!r}, ref={self.is_ref})'

class PhpArray:
    __slots__ = ('data', 'next_int', 'pointer', 'is_globals')
    def __init__(self, data=None):
        self.data = data if data is not None else OrderedDict()
        self.next_int = 0
        self.pointer = 0
        self.is_globals = False
        for k in self.data.keys():
            if isinstance(k, int) and k >= self.next_int:
                self.next_int = k + 1
    def __len__(self): return len(self.data)
    def __repr__(self): return f'PhpArray({dict(self.data)!r})'
    def keys_list(self): return list(self.data.keys())
    def items_list(self): return list(self.data.items())
    def get_cell(self, key, create=False):
        c = self.data.get(key)
        if c is None and create:
            c = Cell(None)
            self.set_cell(key, c)
        return c
    def set_cell(self, key, cell):
        is_new = key not in self.data
        self.data[key] = cell
        if isinstance(key, int) and key >= self.next_int:
            self.next_int = key + 1
        return cell
    def set(self, key, value):
        c = self.data.get(key)
        if c is None:
            c = Cell(value)
            self.set_cell(key, c)
        else:
            c.value = value
        if isinstance(key, int) and key >= self.next_int:
            self.next_int = key + 1
        return c
    def append_cell(self, cell):
        k = self.next_int
        self.set_cell(k, cell)
        return k
    def append(self, value):
        return self.append_cell(Cell(value))
    def delete(self, key):
        if key in self.data:
            # adjust pointer if needed
            keys = self.keys_list()
            try:
                idx = keys.index(key)
                if idx < self.pointer: self.pointer -= 1
            except ValueError: pass
            del self.data[key]
            return True
        return False
    def copy(self, memo=None):
        if memo is None: memo = {}
        oid = id(self)
        if oid in memo: return memo[oid]
        new = PhpArray()
        memo[oid] = new
        new.next_int = self.next_int
        new.pointer = self.pointer
        new.is_globals = False
        for k, c in self.data.items():
            if c.is_ref:
                new.data[k] = c
            else:
                new.data[k] = Cell(copy_value(c.value, memo))
        return new

def copy_value(v, memo=None):
    if isinstance(v, PhpArray):
        return v.copy(memo)
    return v

