def truthy(v):
    if v is None or v is False: return False
    if v is True: return True
    if isinstance(v, int): return v != 0
    if isinstance(v, float): return v != 0.0  # NAN != 0 -> True
    if isinstance(v, bytes): return v != b'' and v != b'0'
    if isinstance(v, PhpArray): return len(v.data) > 0
    return True

_NUMSTR_RE = re.compile(rb'^[ \t\n\r\v\f]*[+-]?((\d+(\.\d*)?)|(\.\d+))([eE][+-]?\d+)?[ \t\n\r\v\f]*$')
_LEADNUM_RE = re.compile(rb'^[ \t\n\r\v\f]*[+-]?((\d+(\.\d*)?)|(\.\d+))([eE][+-]?\d+)?')

def is_numeric_string(s):
    if not isinstance(s, bytes): return False
    return _NUMSTR_RE.match(s) is not None

def parse_numeric_string(s):
    """Return (value, kind) kind: 'int'|'float'|'leading'|'none'"""
    if not isinstance(s, bytes): return (None, 'none')
    t = s.strip(b' \t\n\r\v\f')
    if _NUMSTR_RE.match(s):
        # int form if only sign+digits
        if re.match(rb'^[+-]?\d+$', t):
            try:
                iv = int(t)
                if PHP_INT_MIN <= iv <= PHP_INT_MAX: return (iv, 'int')
                return (float(t), 'float')
            except: return (float(t), 'float')
        try: return (float(t), 'float')
        except: return (None, 'none')
    m = _LEADNUM_RE.match(s)
    if m:
        rest = s[m.end():]
        if rest.strip(b' \t\n\r\v\f') == b'':
            # effectively numeric handled above
            pass
        txt = m.group(0).strip()
        if re.match(rb'^[+-]?\d+$', txt):
            try:
                iv=int(txt)
                if PHP_INT_MIN <= iv <= PHP_INT_MAX: return (iv, 'leading')
            except: pass
            return (float(txt), 'leading')
        return (float(txt), 'leading')
    return (None, 'none')

def trunc_int_from_float(f):
    if math.isnan(f): return 0
    if math.isinf(f): return 0  # PHP (int)INF is 0? platform defined; commonly 0
    iv = int(f)  # trunc toward zero
    # PHP casting float out of int range is undefined-ish; clamps? Python big int -> wrap? Keep clamp as observed? Use wrap64 for huge?
    if iv > PHP_INT_MAX or iv < PHP_INT_MIN:
        # Observed on Linux x86_64 zend casts using cvttsd2si gives PHP_INT_MIN for out of range? We'll return PHP_INT_MIN? Actually (int)1e20 gives -9223372036854775808? check later. Keep wrap via int64 cast semantics of C: use struct?
        # Use modulo wrap approximation
        return wrap64(iv)
    return iv

def float_format_precision(v, precision=14):
    if math.isnan(v): return 'NAN'
    if math.isinf(v): return 'INF' if v>0 else '-INF'
    if v == 0.0:
        return '-0' if math.copysign(1.0, v) < 0 else '0'
    if precision is None or precision < 0: precision = 14
    if precision == 0: precision = 1
    s = format(v, f'.{precision}g')
    return _normalize_exp(s)

def _normalize_exp(s):
    if 'e' in s or 'E' in s:
        mant, exp = re.split('[eE]', s)
        if '.' not in mant: mant += '.0'
        e = int(exp)
        return f"{mant}E{'+' if e>=0 else '-'}{abs(e)}"
    return s

def float_format_serialize(v, serialize_precision=-1, for_var_export=False):
    if math.isnan(v): return 'NAN'
    if math.isinf(v): return 'INF' if v>0 else '-INF'
    if v == 0.0:
        neg = math.copysign(1.0, v) < 0
        if for_var_export: return '-0.0' if neg else '0.0'
        return '-0' if neg else '0'
    if serialize_precision is not None and serialize_precision >= 0:
        # use precision digits like gcvt with that precision (like precision for echo but ser)
        s = format(v, f'.{max(1,serialize_precision)}g')
        s = _normalize_exp(s)
        if for_var_export and 'E' not in s and '.' not in s: s += '.0'
        if not for_var_export and 'E' not in s and s.endswith('.0'): s = s[:-2]
        return s
    # shortest repr
    s = repr(v)  # python shortest
    # Python uses e.g. 1e+20, 1.0, 100000.0
    if 'e' in s or 'E' in s:
        # PHP threshold: if exponent representation but value is not too big/small, php may use decimal? Python switches at 1e16 / 1e-5 similar
        s2 = _normalize_exp(s)
        return s2
    if s.endswith('.0'):
        if for_var_export: return s
        return s[:-2]
    return s

def php_float_to_bytes(v, precision=14):
    return float_format_precision(v, precision).encode()

def array_key_normalize(k, interp=None, frame=None, line=1):
    """Normalize array key; may raise PhpThrown via interp for illegal types."""
    if isinstance(k, bool): return 1 if k else 0
    if isinstance(k, int): return k
    if isinstance(k, float):
        # PHP 8.1: implicit conversion float to int loses precision deprecated if fractional; warnings handled by caller ideally
        return trunc_int_from_float(k)
    if k is None: return b''
    if isinstance(k, bytes):
        # canonical decimal integer string (no leading zeros except 0 itself, no plus, optional minus)
        if re.match(rb'^-?(0|[1-9]\d*)$', k):
            try:
                iv = int(k)
                if PHP_INT_MIN <= iv <= PHP_INT_MAX: return iv
            except: pass
        return k
    if isinstance(k, PhpResource):
        return k.id
    # illegal offset type
    if interp is not None:
        interp.throw_error('TypeError', f'Illegal offset type', frame, line)
    raise TypeError('Illegal offset type')

def key_display(k):
    if isinstance(k, int): return str(k)
    return sstr(k)

