def token_display(tok):
    if tok is None: return 'end of file'
    t=tok.type; v=tok.value
    if t=='EOF': return 'end of file'
    if t=='INT': return f'integer "{v}"'
    if t=='FLOAT': return f'floating-point number "{v}"'
    if t=='STRING': 
        try: s=v.decode('utf-8','replace')
        except: s='?'
        return f'string "{s}"'
    if t=='DSTRING': return 'encapsed string'
    if t=='VAR': return f'variable "${v}"'
    if t=='IDENT':
        if v.lower() in KEYWORDS: return f'token "{v}"'
        return f'identifier "{v}"'
    if t=='INLINE': return 'inline HTML'
    if t in ('OPEN','CLOSE','OPEN_ECHO'): return f'token "{ "<?php" if t!="CLOSE" else "?> "}"'
    return f'token "{t}"'

