        if self.is_kw('do'): return self.parse_do()
        if self.is_kw('for'): return self.parse_for()
        if self.is_kw('foreach'): return self.parse_foreach()
        if self.is_kw('switch'): return self.parse_switch()
        if self.is_kw('try'): return self.parse_try()
        if self.is_kw('declare'): return self.parse_declare()
        if self.is_kw('namespace'): return self.parse_namespace()
        if self.is_kw('use'): return self.parse_use_stmt()
        if self.is_kw('global'):
            self.advance(); vars_=[]
            while True:
                vars_.append(self.parse_expr())
                if not self.match(','): break
            self.expect_semi(); return ('global',line,vars_)
        if self.is_kw('const'):
            self.advance(); consts=[]
            while True:
                nm=self.expect('IDENT').value; self.expect('='); val=self.parse_expr(); consts.append((nm,val))
                if not self.match(','): break
            self.expect_semi(); return ('const_decl',line,consts,self.current_namespace)
        if self.is_kw('static'):
            # static $x [= v], ...
            if self.peek(1).type=='VAR':
                self.advance(); vars_=[]
                while True:
                    vt=self.expect('VAR'); default=None
                    if self.match('='): default=self.parse_expr()
                    vars_.append((vt.value,default))
                    if not self.match(','): break
                self.expect_semi(); return ('static_vars',line,vars_)
            # else fall thru expr (static::, static function, static fn)
        if self.is_kw('unset'):
            # unset(...) as statement (also parseable as expr, but handle here)
            e=self.parse_expr(); self.expect_semi(); return ('expr_stmt',line,e)
        # expression statement
        e=self.parse_expr()
        # attributes on closure expression ignored
        self.expect_semi(); return ('expr_stmt',line,e)
    # control
    def parse_if(self):
        line=self.cur().line; self.expect_kw('if'); self.expect('('); cond=self.parse_expr(); self.expect(')')
        if self.match(':'):
            arms=[]
            body=self.parse_statements(stop_keywords={'elseif','else','endif'})
            arms.append((cond,('block',line,body)))
            while self.is_kw('elseif'):
                self.advance(); self.expect('('); c=self.parse_expr(); self.expect(')'); self.expect(':')
                b=self.parse_statements(stop_keywords={'elseif','else','endif'}); arms.append((c,('block',line,b)))
            else_block=None
            if self.is_kw('else'):
                self.advance(); self.expect(':'); b=self.parse_statements(stop_keywords={'endif'}); else_block=('block',line,b)
            self.expect_kw('endif'); self.expect_semi()
            return ('if',line,arms,else_block)
        arms=[(cond,self.parse_single_or_block())]
        while self.is_kw('elseif'):
            self.advance(); self.expect('('); c=self.parse_expr(); self.expect(')'); arms.append((c,self.parse_single_or_block()))
        else_block=None
        if self.is_kw('else'):
            self.advance()
            if self.is_kw('if'): else_block=('block',line,[self.parse_if()])
            else: else_block=self.parse_single_or_block()
        return ('if',line,arms,else_block)
    def parse_while(self):
        line=self.cur().line; self.expect_kw('while'); self.expect('('); cond=self.parse_expr(); self.expect(')')
        if self.match(':'):
            body=self.parse_statements(stop_keywords={'endwhile'}); self.expect_kw('endwhile'); self.expect_semi(); return ('while',line,cond,('block',line,body))
        return ('while',line,cond,self.parse_single_or_block())
    def parse_do(self):
        line=self.cur().line; self.expect_kw('do'); body=self.parse_single_or_block(); self.expect_kw('while'); self.expect('('); cond=self.parse_expr(); self.expect(')'); self.expect_semi(); return ('do',line,cond,body)
    def parse_expr_list_until(self,delim):
        lst=[]
        if self.cur().type==delim: return lst
        lst.append(self.parse_expr())
        while self.match(','): lst.append(self.parse_expr())
        return lst
    def parse_for(self):
        line=self.cur().line; self.expect_kw('for'); self.expect('(')
        init=self.parse_expr_list_until(';'); self.expect(';')
        cond=self.parse_expr_list_until(';'); self.expect(';')
        loop=self.parse_expr_list_until(')'); self.expect(')')
        if self.match(':'):
            body=self.parse_statements(stop_keywords={'endfor'}); self.expect_kw('endfor'); self.expect_semi(); return ('for',line,init,cond,loop,('block',line,body))
        return ('for',line,init,cond,loop,self.parse_single_or_block())
    def parse_foreach(self):
        line=self.cur().line; self.expect_kw('foreach'); self.expect('('); expr=self.parse_expr(); self.expect_kw('as')
        first=self.parse_expr(); key=None; value=first
        if self.match('=>'): key=first; value=self.parse_expr()
        self.expect(')')
        if self.match(':'):
            body=self.parse_statements(stop_keywords={'endforeach'}); self.expect_kw('endforeach'); self.expect_semi(); return ('foreach',line,expr,key,value,('block',line,body))
        return ('foreach',line,expr,key,value,self.parse_single_or_block())
    def parse_switch(self):
        line=self.cur().line; self.expect_kw('switch'); self.expect('('); subj=self.parse_expr(); self.expect(')')
        colon=False
        if self.match('{'): colon=False
        elif self.match(':'): colon=True
        else: self.error(expecting='"{" or ":"')
        # optional semicolon after { in php? switch {; case...
        if not colon: self.match(';')
        cases=[]
        while not self.at_eof():
            if not colon and self.cur().type=='}': self.advance(); break
            if colon and self.is_kw('endswitch'): self.advance(); self.expect_semi(); break
            if self.is_kw('case'):
                self.advance(); ce=self.parse_expr()
                if not (self.match(':') or self.match(';')): self.error(expecting='":"')
            elif self.is_kw('default'):
                self.advance(); ce=None
                if not (self.match(':') or self.match(';')): self.error(expecting='":"')
            else:
                self.error(expecting='"case" or "default"')
            body=self.parse_statements(stop_keywords={'case','default','endswitch'},stop_types={'}'} if not colon else set())
            cases.append((ce,body))
        return ('switch',line,subj,cases)
    def parse_try(self):
        line=self.cur().line; self.expect_kw('try'); body=self.parse_block_statements() if self.cur().type=='{' else self.parse_single_or_block()
        catches=[]
        while self.is_kw('catch'):
            self.advance(); self.expect('('); types=[]
            while True:
                # type names, possibly leading backslash
                segs,abs_=self.parse_name_segments(); 
                if segs:
                    _,res=self.resolve_name(segs,abs_,'class'); types.append(res)
                if not self.match('|'): break
            var=None
            if self.cur().type=='VAR': var=self.advance().value
            self.expect(')'); cbody=self.parse_block_statements() if self.cur().type=='{' else self.parse_single_or_block()
            catches.append((types,var,cbody))
        finally_block=None
        if self.is_kw('finally'):
            self.advance(); finally_block=self.parse_block_statements() if self.cur().type=='{' else self.parse_single_or_block()
        return ('try',line,body,catches,finally_block)
    def parse_declare(self):
        line=self.cur().line; self.expect_kw('declare'); self.expect('('); opts=[]
        while True:
            nm=self.expect('IDENT').value; self.expect('='); val=self.parse_expr(); opts.append((nm,val))
            if not self.match(','): break
        self.expect(')')
        if self.cur().type=='{': body=self.parse_block_statements(); return ('declare',line,opts,body)
        if self.match(':'):
            body=self.parse_statements(stop_keywords={'enddeclare'}); self.expect_kw('enddeclare'); self.expect_semi(); return ('declare',line,opts,('block',line,body))
        self.expect_semi(); return ('declare',line,opts,None)
    def parse_namespace(self):
        line=self.cur().line; self.expect_kw('namespace')
        if self.cur().type=='{':
            saved_ns=self.current_namespace; saved=(dict(self.alias_class),dict(self.alias_func),dict(self.alias_const))
            self.current_namespace=''; self.alias_class={}; self.alias_func={}; self.alias_const={}
            body=self.parse_block_statements()
            self.current_namespace=saved_ns; self.alias_class,self.alias_func,self.alias_const=saved
            return ('namespace_block',line,'',body)
        segs,_=self.parse_name_segments(); ns='\\'.join(segs)
        if self.cur().type=='{':
            saved_ns=self.current_namespace; saved=(dict(self.alias_class),dict(self.alias_func),dict(self.alias_const))
            self.current_namespace=ns; self.alias_class={}; self.alias_func={}; self.alias_const={}
            body=self.parse_block_statements()
            self.current_namespace=saved_ns; self.alias_class,self.alias_func,self.alias_const=saved
            return ('namespace_block',line,ns,body)
        self.expect_semi(); self.current_namespace=ns; self.alias_class={}; self.alias_func={}; self.alias_const={}
        return ('namespace_decl',line,ns)
    def parse_use_stmt(self):
        line=self.cur().line; self.expect_kw('use')
        kind='class'
        if self.is_kw('function'): self.advance(); kind='function'
        elif self.is_kw('const'): self.advance(); kind='const'
        # group use: Prefix\{ ... }
        # Need lookahead: parse name segments, if next \ {?? tokens: '\' then '{'
        save=self.pos
        segs,abs_=self.parse_name_segments()
        if self.cur().type=='\\' and self.peek(1).type=='{':
            prefix='\\'.join(segs); self.advance(); self.expect('{')
            while True:
                k2=kind
                if self.is_kw('function'): self.advance(); k2='function'
                elif self.is_kw('const'): self.advance(); k2='const'
                s2,_=self.parse_name_segments(); target=prefix+'\\'+'\\'.join(s2); alias=s2[-1] if s2 else ''
                if self.is_kw('as'): self.advance(); alias=self.expect('IDENT').value
                self._register_alias(k2,alias,target)
                if not self.match(','): break
                if self.cur().type=='}': break
            self.expect('}'); self.expect_semi(); return ('noop',line)
        # normal list: first already parsed
        items=[segs]
        # we consumed first, handle it in loop structure
        while True:
            s=items.pop(0) if items else self.parse_name_segments()[0]
            target='\\'.join(s); alias=s[-1] if s else ''
            if self.is_kw('as'): self.advance(); alias=self.expect('IDENT').value
            self._register_alias(kind,alias,target)
            if not self.match(','): break
        self.expect_semi(); return ('noop',line)
    def _register_alias(self,kind,alias,target):
        if kind=='class': self.alias_class[alias.lower()]=target
        elif kind=='function': self.alias_func[alias.lower()]=target
        else: self.alias_const[alias]=target; self.alias_const[alias.lower()]=target
    # attributes
    def parse_attributes(self):
        attrs=[]
        while self.cur().type=='#[':
            self.advance()
            while True:
                name=self.parse_resolved_class_name(); args=[]
                if self.match('('): args=self.parse_args_until_rparen()
                attrs.append(('attribute',self.cur().line,name,args))
                if not self.match(','): break
            self.expect(']')
        return attrs
    # types
    def try_parse_type(self, required=False):
        # Determine if a type starts here
        t=self.cur()
        starts = t.type in ('?','(','\\') or t.type=='IDENT'
        if not starts: return None
        # If ident is something that will be e.g. fn name... in param context, ident before $var is type
        return self.parse_type()
    def parse_type_atom(self):
        if self.match('('):
            inner=self.parse_type(); self.expect(')'); return f'({inner})'
        if self.cur().type=='\\' or self.cur().type=='IDENT':
            segs,abs_=self.parse_name_segments()
            if not segs: self.error(expecting='type')
            low='\\'.join(segs).lower()
            if len(segs)==1 and low in ('int','float','string','bool','array','object','mixed','void','never','null','false','true','iterable','callable','self','static','parent'): return low
            _,res=self.resolve_name(segs,abs_,'class'); return res
        self.error(expecting='type')
    def parse_type(self):
        nullable=False
        if self.match('?'): nullable=True
        parts=[self.parse_type_atom()]
        op=None
        while self.cur().type in ('|','&'):
            op=self.advance().type; parts.append(self.parse_type_atom())
        if len(parts)>1: ty=op.join(parts)
        else: ty=parts[0]
        if nullable: ty='?'+ty
        return ty
    # params
    def parse_params(self):
        params=[]; self.expect('(')
        if self.match(')'): return params
        while True:
            pattrs=[]
            if self.cur().type=='#[': pattrs=self.parse_attributes()
            promoted_vis=None; promoted_ro=False
            # promoted visibility (only meaningful constructors; parser accept anywhere)
            while self.cur().type=='IDENT' and self.cur().value.lower() in ('public','protected','private'):
                promoted_vis=self.advance().value.lower()
                # asymmetric private(set) following?
                if self.cur().type=='(' and self.peek(1).type=='IDENT' and self.peek(1).value.lower()=='set':
                    self.advance(); self.advance(); self.expect(')'); promoted_vis=promoted_vis  # ignore set vis for param
            if self.is_kw('readonly'): self.advance(); promoted_ro=True
            ptype=None
            # type if next is not directly &, ..., VAR
            if self.cur().type not in ('&','...','VAR'):
                # Could be type or nothing; if IDENT/?/(\ then type
                if self.cur().type in ('IDENT','?','(','\\'): ptype=self.parse_type()
            byref=False; variadic=False
            if self.match('&'): byref=True
            if self.match('...'): variadic=True
            vt=self.expect('VAR'); name=vt.value
            default=None; has=False
            if self.match('='): default=self.parse_expr(); has=True
            params.append(Param(name,ptype,byref,variadic,default,has,promoted_vis,promoted_ro,pattrs))
            if not self.match(','): break
            if self.cur().type==')': break
        self.expect(')'); return params
    def parse_function_decl(self,attrs,mods):
        line=self.cur().line
        # mods not used for functions (final etc for methods handled elsewhere)
        self.expect_kw('function'); byref=bool(self.match('&')); name=self.expect('IDENT').value
        params=self.parse_params(); ret=None
        if self.match(':'): ret=self.parse_type()
        body=None
        if self.cur().type=='{': body=self.parse_block_statements()
        elif self.match(';'): body=None
        else: self.error(expecting='"{"')
        full=(self.current_namespace+'\\'+name) if self.current_namespace else name
        func=PhpFunction(name=full,params=params,body=body,return_type=ret,byref_return=byref,namespace=self.current_namespace,file=self.filename,line=line,attributes=attrs)
        func.end_line=self.cur().line
        return ('function_decl',line,func)
    def parse_function_like_body(self, name_for_func='', attrs=None, is_method=False):
        # after 'function', parse optional &, optional name (methods/decls already handled outside? This is for closures)
        pass
    # class decl
    def parse_class_decl(self,attrs,mods):
        line=self.cur().line; kind=self.advance().value.lower()  # class/interface/trait/enum
        name=self.expect('IDENT').value
        info=self.parse_class_body(kind,name,attrs,mods,line,anon=False)
        return ('class_decl',line,info)
    def parse_class_body(self,kind,name,attrs,mods,line,anon=False,anon_args=None):
        backing=None
        if kind=='enum' and self.match(':'): backing=self.parse_type()
        parent=None; interfaces=[]
        if self.is_kw('extends'):
            self.advance()
            if kind=='interface':
                interfaces.append(self.parse_resolved_class_name())
                while self.match(','): interfaces.append(self.parse_resolved_class_name())
                parent=None
            else:
                parent=self.parse_resolved_class_name()
        if self.is_kw('implements'):
            self.advance(); interfaces.append(self.parse_resolved_class_name())
            while self.match(','): interfaces.append(self.parse_resolved_class_name())
        self.expect('{')
        methods=[]; props=[]; consts=[]; trait_uses=[]; enum_cases=[]
        self.in_class_depth+=1
        while self.cur().type!='}' and not self.at_eof():
            if self.cur().type=='OPEN': self.advance(); continue
            if self.cur().type==';': self.advance(); continue
            mattrs=[]
            if self.cur().type=='#[': mattrs=self.parse_attributes()
            if kind=='enum' and self.is_kw('case'):
                self.advance(); cname=self.expect('IDENT').value; cval=None
                if self.match('='): cval=self.parse_expr()
                self.expect(';'); enum_cases.append((cname,cval,mattrs)); continue
            if self.is_kw('use'):
                # trait use
                self.advance(); tnames=[self.parse_resolved_class_name()]
                while self.match(','): tnames.append(self.parse_resolved_class_name())
                adaptations=[]
                if self.cur().type=='{':
                    self.advance()
                    while self.cur().type!='}' and not self.at_eof():
                        adaptations.append(self.parse_trait_adaptation())
                    self.expect('}')
                else: self.expect(';')
                trait_uses.append((tnames,adaptations)); continue
            # modifiers
            vis=None; set_vis=None; static=False; abstract=False; final=False; readonly=False; var_kw=False
            while self.cur().type=='IDENT' and self.cur().value.lower() in ('public','protected','private','static','abstract','final','readonly','var'):
                w=self.advance().value.lower()
                if w in ('public','protected','private'):
                    # asymmetric: private(set) etc
                    if self.cur().type=='(' and self.peek(1).type=='IDENT' and self.peek(1).value.lower()=='set':
                        self.advance(); self.advance(); self.expect(')'); set_vis=w
                    else:
                        if vis is None: vis=w
                        else: set_vis=w  # e.g. public private(set) handled previous iteration? second visibility is set_vis
                elif w=='static': static=True
                elif w=='abstract': abstract=True
                elif w=='final': final=True
                elif w=='readonly': readonly=True
                elif w=='var': var_kw=True; vis=vis or 'public'
            if self.is_kw('const'):
                self.advance(); ctype=None
                # typed const if next ident followed by ident, or ?, \(, (
                if self.cur().type in ('?','(','\\') or (self.cur().type=='IDENT' and self.peek(1).type=='IDENT'):
                    try: ctype=self.parse_type()
                    except Exception: ctype=None
                while True:
                    cname=self.expect('IDENT').value; self.expect('='); cval=self.parse_expr()
                    consts.append(ConstDef(cname,UNDEF,vis or 'public',final,ctype,None,cval))
                    if not self.match(','): break
                self.expect(';'); continue
            if self.is_kw('function'):
                mline=self.cur().line; self.advance(); byref=bool(self.match('&'))
                mname=self.expect('IDENT').value; params=self.parse_params(); ret=None
                if self.match(':'): ret=self.parse_type()
                body=None
                if self.cur().type=='{': body=self.parse_block_statements()
                elif self.match(';'): body=None; abstract=True if kind=='interface' else abstract
                else: self.error(expecting='"{" or ";"')
                full_simple=mname
                func=PhpFunction(name=full_simple,params=params,body=body,return_type=ret,byref_return=byref,namespace=self.current_namespace,file=self.filename,line=mline,attributes=mattrs)
                func.end_line=self.cur().line
                methods.append(MethodDef(mname,func,vis or 'public',static,abstract,final,None)); continue
            # property
            ptype=None
            if self.cur().type!='VAR':
                if self.cur().type in ('IDENT','?','(','\\'): ptype=self.parse_type()
            while True:
                vt=self.expect('VAR'); pname=vt.value; default=None; has=False
                if self.match('='): default=self.parse_expr(); has=True
                hooks={}
                if self.cur().type=='{': hooks=self.parse_property_hooks()
                props.append(PropDef(pname,vis or 'public',static,ptype,default,has,UNDEF,readonly,None,set_vis,hooks,mattrs))
                if not self.match(','): break
            self.expect(';')
        self.expect('}'); self.in_class_depth-=1
        if anon:
            self.anon_counter+=1
            full=f'class@anonymous\x00{self.filename}:{line}${self.anon_counter-1}' if False else f'class@anonymous\x00{self.filename}:{line}${id(object())%1000}'
            # Deterministic counter based on anon_counter before increment? Use stored counter in info patched by parse_new
            full=name  # name already generated by caller
        else:
            full=(self.current_namespace+'\\'+name) if self.current_namespace else name
        info={'name':full,'simple_name':name,'kind':kind,'parent':parent,'interfaces':interfaces,'methods':methods,'props':props,'consts':consts,'trait_uses':trait_uses,'enum_cases':enum_cases,'enum_backing':backing,'mods':mods,'attrs':attrs,'line':line,'file':self.filename,'namespace':self.current_namespace,'anon':anon,'end_line':self.cur().line}
        return info
    def parse_trait_adaptation(self):
        line=self.cur().line
        # parse [TraitName::] method, then as/insteadof
        first=None; method=None; trait=None
        segs,abs_=self.parse_name_segments()
        if self.cur().type=='::':
            self.advance(); trait='\\'.join(segs); _,trait=self.resolve_name(segs,abs_,'class'); method=self.expect('IDENT').value
        else:
            method=segs[-1] if segs else ''
        adapt={'trait':trait,'method':method,'alias':None,'visibility':None,'insteadof':[]}
        if self.is_kw('as'):
            self.advance()
            if self.cur().type=='IDENT' and self.cur().value.lower() in ('public','protected','private'):
                adapt['visibility']=self.advance().value.lower()
            if self.cur().type=='IDENT': adapt['alias']=self.advance().value
        elif self.is_kw('insteadof'):
            self.advance()
            while True:
                adapt['insteadof'].append(self.parse_resolved_class_name())
                if not self.match(','): break
        self.expect(';'); return adapt
    def parse_property_hooks(self):
        hooks={}; self.expect('{')
        while self.cur().type!='}' and not self.at_eof():
            if self.cur().type=='#[': self.parse_attributes()
            # modifiers final etc ignored
            while self.is_kw('final') or self.is_kw('abstract'): self.advance()
            if self.is_kw('get'):
                self.advance()
                if self.match(';'): hooks['get']=None
                elif self.match('=>'): e=self.parse_expr(); self.expect(';'); hooks['get']=('expr',e)
                elif self.cur().type=='{': hooks['get']=('block',self.parse_block_statements())
            elif self.is_kw('set'):
                self.advance(); params=[]
                if self.cur().type=='(': params=self.parse_params()
                if self.match(';'): hooks['set']=(params,None)
                elif self.match('=>'): e=self.parse_expr(); self.expect(';'); hooks['set']=(params,('expr',e))
                elif self.cur().type=='{': hooks['set']=(params,('block',self.parse_block_statements()))
            else:
                # unknown token, skip til semi or }
                self.advance()
        self.expect('}'); return hooks
    # arguments
    def parse_args_until_rparen(self):
        args=[]
        if self.match(')'): return args
        while True:
            args.append(self.parse_arg())
            if not self.match(','): break
            if self.cur().type==')': break
        self.expect(')'); return args
    def parse_arg(self):
        line=self.cur().line
        if self.match('...'):
            e=self.parse_expr(); return ('arg',line,None,e,True)
        # named argument IDENT :
        if self.cur().type=='IDENT' and self.peek(1).type==':':
            # but ensure not label-like in ternary - in arg position this is named
            nm=self.advance().value; self.advance(); e=self.parse_expr(); return ('arg',line,nm,e,False)
        e=self.parse_expr(); return ('arg',line,None,e,False)
    def parse_call_args(self):
        # current '('
        self.expect('(')
        if self.cur().type=='...' and self.peek(1).type==')':
            self.advance(); self.advance(); return 'FCC'
        return self.parse_args_until_rparen()
    # expressions
    def current_binop(self):
        t=self.cur()
        if t.type in BINPREC: return (t.type,BINPREC[t.type])
        if t.type=='IDENT':
            low=t.value.lower()
            if low in ('and','xor','or','instanceof'): return (low,BINPREC[low])
        return None
    def parse_expr(self,min_prec=0):
        line=self.cur().line
        lhs=self.parse_unary()
        while True:
            t=self.cur()
            if t.type in ASSIGN_OPS and min_prec<=40:
                op=self.advance().type
                if op=='=&':
                    rhs=self.parse_expr(40); lhs=('assign_ref',line,lhs,rhs); continue
                rhs=self.parse_expr(40); lhs=('assign',line,op,lhs,rhs); continue
            if t.type=='?' and min_prec<=50:
                self.advance()
                if self.cur().type==':':
                    self.advance(); els=self.parse_expr(51); lhs=('ternary',line,lhs,None,els); continue
                mid=self.parse_expr(); self.expect(':'); els=self.parse_expr(51); lhs=('ternary',line,lhs,mid,els); continue
            b=self.current_binop()
            if not b: break
            op,prec=b
            if prec < min_prec: break
            self.advance()
            if op in ('**','??'):
                rhs=self.parse_expr(prec)
            elif op=='|>':
                rhs=self.parse_expr(prec+1); lhs=('pipe',line,lhs,rhs); continue
            elif op=='instanceof':
                # right side is class name or expression
                rhs=self.parse_instanceof_rhs(); lhs=('instanceof',line,lhs,rhs); continue
            else:
                rhs=self.parse_expr(prec+1)
            # non-associative check
            if prec in (120,130):
                nb=self.current_binop()
                if nb and nb[1]==prec:
                    self.error()
            lhs=('binop',line,op,lhs,rhs)
        return lhs
    def parse_instanceof_rhs(self):
        line=self.cur().line
        # variable holding class name, or class name
        if self.cur().type=='VAR' or self.cur().type=='$':
            return self.parse_unary()
        segs,abs_=self.parse_name_segments()
        if segs:
            _,res=self.resolve_name(segs,abs_,'class'); return ('classname',line,res,'\\'.join(segs))
        return self.parse_unary()
    def parse_unary(self):
        t=self.cur(); line=t.line
        if t.type in ('!','~','+','-'):
            op=self.advance().type; operand=self.parse_expr(180); return ('unary',line,op,operand)
        if t.type in ('++','--'):
            op=self.advance().type; operand=self.parse_unary(); return ('preinc',line,op,operand)
        if t.type=='@':
            self.advance(); operand=self.parse_expr(180); return ('suppress',line,operand)
        if t.type=='&':
            self.advance(); operand=self.parse_unary(); return ('ref',line,operand)
        if t.type=='(':
            # cast lookahead
            if self.peek(1).type=='IDENT' and self.peek(1).value.lower() in CAST_TYPES and self.peek(2).type==')':
                self.advance(); ctype=self.advance().value.lower(); self.advance(); operand=self.parse_expr(180); return ('cast',line,ctype,operand)
        if self.is_kw('clone'):
            self.advance()
            # PHP 8.5 clone(expr, array) form? If '(' and next isn't starting a parenthesized expr ambiguously, still parse clone primary normally
            operand=self.parse_unary(); return ('clone',line,operand)
        node=self.parse_primary()
        node=self.parse_postfix(node)
        return node
    def parse_postfix(self,node):
        while True:
            t=self.cur(); line=t.line
            if t.type=='(':
                args=self.parse_call_args()
                if args=='FCC': node=('fcallable',line,node)
                elif node[0]=='func_name':
                    node=('func_call',line,node[2],node[3],args)
                elif node[0]=='method_ref':
                    # ('method_ref',line,obj,name_node,nullsafe)
                    node=('method_call',line,node[2],node[3],args,node[4])
                elif node[0]=='static_method_ref':
                    node=('static_call',line,node[2],node[3],args)
                else:
                    node=('call',line,node,args)
                continue
            if t.type=='[':
                self.advance()
                if self.match(']'): node=('dim',line,node,None); continue
                idx=self.parse_expr(); self.expect(']'); node=('dim',line,node,idx); continue
            if t.type in ('->','?->'):
                nullsafe=(t.type=='?->'); self.advance()
                name_node=self.parse_member_name()
                node=('method_ref',line,node,name_node,nullsafe)
                # If not followed by '(' it is property fetch; convert at end of loop? Keep as method_ref and final conversion below after loop can't know. We'll immediately if next isn't '(' transform to prop
                if self.cur().type!='(':
                    node=('prop',line,node,name_node,nullsafe)
                continue
            if t.type=='::':
                self.advance()
                # ::class
                if self.is_kw('class'):
                    self.advance(); node=('class_const',line,node); continue
                if self.cur().type=='VAR':
                    nm=self.advance().value; node=('static_prop',line,node,('member',line,nm)); continue
                if self.cur().type=='$':
                    # dynamic static prop ${expr} etc
                    e=self.parse_unary(); node=('static_prop_expr',line,node,e); continue
                name_node=self.parse_member_name()
                if self.cur().type=='(':
                    node=('static_method_ref',line,node,name_node)
                else:
                    node=('class_const_fetch',line,node,name_node)
                continue
            if t.type in ('++','--'):
                op=self.advance().type; node=('postinc',line,op,node); continue
            break
        return node
    def parse_member_name(self):
        line=self.cur().line
        if self.cur().type=='IDENT': return ('member',line,self.advance().value)
        if self.cur().type=='VAR': return ('var',line,self.advance().value)
        if self.cur().type=='{':
            self.advance(); e=self.parse_expr(); self.expect('}'); return e
        if self.cur().type=='$':
            return self.parse_unary()
        self.error(expecting='identifier')
    def parse_primary(self):
        t=self.cur(); line=t.line
        if t.type=='INT': self.advance(); return ('int',line,t.value)
        if t.type=='FLOAT': self.advance(); return ('float',line,t.value)
        if t.type=='STRING': self.advance(); return ('string',line,t.value)
        if t.type=='DSTRING':
            self.advance(); parts,kind=t.value
            nodes=[]
            for p in parts:
                if p[0]=='lit': nodes.append(('string',line,p[1]))
                elif p[0]=='var': nodes.append(('var',line,p[1]))
                elif p[0]=='var_dim':
                    _,nm,idx=p
                    if idx[0]=='int': inode=('int',line,idx[1])
                    elif idx[0]=='str': inode=('string',line,idx[1])
                    else: inode=('var',line,idx[1])
                    nodes.append(('dim',line,('var',line,nm),inode))
                elif p[0]=='var_prop': nodes.append(('prop',line,('var',line,p[1]),('member',line,p[2]),False))
                elif p[0]=='curly':
                    sub=self.parse_subexpr(p[1],line); nodes.append(sub)
            return ('interp_string',line,nodes,kind)
        if t.type=='VAR': self.advance(); return ('var',line,t.value)
        if t.type=='$':
            self.advance()
            if self.match('{'):
                e=self.parse_expr(); self.expect('}'); return ('varvar',line,e)
            if self.cur().type=='VAR':
                v=self.advance().value; return ('varvar',line,('var',line,v))
            if self.cur().type=='$':
                # $$$a etc
                inner=self.parse_primary(); return ('varvar',line,inner)
            self.error(expecting='variable')
        if t.type=='(':
            self.advance(); e=self.parse_expr(); self.expect(')'); return e
        if t.type=='[':
            return self.parse_array_literal()
        if t.type=='#[':
            attrs=self.parse_attributes(); node=self.parse_primary(); return node
        if t.type=='\\':
            # absolute name
            return self.parse_name_primary()
        if t.type=='IDENT':
            low=t.value.lower()
            if low=='true': self.advance(); return ('bool',line,True)
            if low=='false': self.advance(); return ('bool',line,False)
            if low=='null': self.advance(); return ('null',line)
            if low=='array' and self.peek(1).type=='(':
                self.advance(); self.expect('('); entries=self.parse_array_entries(')'); self.expect(')'); return ('array',line,entries)
            if low=='print':
                self.advance(); e=self.parse_expr(60); return ('print',line,e)
            if low=='yield':
                self.advance()
                if self.is_kw('from'):
                    self.advance(); e=self.parse_expr(60); return ('yield_from',line,e)
                # yield [key=>]value , bare yield in contexts like ; ) , etc
                if self.cur().type in (';',')',',']','}'): return ('yield',line,None,None)
                e=self.parse_expr(60)
                if self.match('=>'):
                    v=self.parse_expr(60); return ('yield',line,e,v)
                return ('yield',line,None,e)
            if low=='throw':
                self.advance(); e=self.parse_expr(60); return ('throw_expr',line,e)
            if low in ('include','include_once','require','require_once'):
                self.advance(); e=self.parse_expr(60); return ('include',line,low,e)
            if low=='eval':
                self.advance(); self.expect('('); e=self.parse_expr(); self.expect(')'); return ('eval',line,e)
            if low in ('exit','die'):
                self.advance(); arg=None
                if self.match('('):
                    arg=None if self.cur().type==')' else self.parse_expr()
                    self.expect(')')
                elif self.cur().type not in (';',',',')'):
                    # die "msg" forms - only if likely primary start? Use parse_unary
                    try: arg=self.parse_unary()
                    except Exception: arg=None
                return ('exit',line,arg)
            if low=='isset':
                self.advance(); self.expect('('); args=[]
                if self.cur().type!=')':
                    args.append(self.parse_expr())
                    while self.match(','): 
                        if self.cur().type==')': break
                        args.append(self.parse_expr())
                self.expect(')'); return ('isset',line,args)
            if low=='empty':
                self.advance(); self.expect('('); e=self.parse_expr(); self.expect(')'); return ('empty',line,e)
            if low=='list' and self.peek(1).type=='(':
                self.advance(); self.expect('('); entries=self.parse_destructure_entries(')'); return ('list',line,entries)
            if low=='new': return self.parse_new()
            if low=='match' and self.peek(1).type=='(':
                return self.parse_match()
            if low=='fn': return self.parse_closure()
            if low=='function': return self.parse_closure()
            if low=='static':
                # static fn/function closures, static:: , static as class name
                if self.peek(1).type=='IDENT' and self.peek(1).value.lower() in ('fn','function'): return self.parse_closure()
                return self.parse_name_primary()
            if low in ('self','parent'):
                return self.parse_name_primary()
            return self.parse_name_primary()
        self.error()
    def parse_subexpr(self,text,line):
        lx=Lexer(text,self.filename,start_in_php=True,short_open_tag=self._short_tag if hasattr(self,'_short_tag') else True)
        toks=lx.tokenize()
        sub=Parser(toks,self.filename); sub.current_namespace=self.current_namespace; sub.alias_class=dict(self.alias_class); sub.alias_func=dict(self.alias_func); sub.alias_const=dict(self.alias_const)
        e=sub.parse_expr()
        return e
    def parse_name_primary(self):
        line=self.cur().line
        segs,abs_=self.parse_name_segments()
        if not segs: self.error(expecting='identifier')
        display='\\'.join(segs)
        # class name if :: following
        if self.cur().type=='::':
            _,res=self.resolve_name(segs,abs_,'class'); return ('classname',line,res,display)
        if self.cur().type=='(':
            _,cands=self.resolve_name(segs,abs_,'function'); return ('func_name',line,cands,display)
        # constant
        _,cands=self.resolve_name(segs,abs_,'const'); return ('const',line,cands,display)
    def parse_array_literal(self):
        line=self.cur().line; self.expect('['); entries=self.parse_array_entries(']'); self.expect(']'); return ('array',line,entries)
    def parse_array_entries(self,closer):
        entries=[]
        if self.cur().type==closer: return entries
        while True:
            if self.match('...'):
                e=self.parse_expr(); entries.append((None,e,True))
            else:
                first=self.parse_expr()
                if self.match('=>'):
                    # value can be &...
                    if self.cur().type=='&':
                        line=self.cur().line; self.advance(); v=('ref',line,self.parse_unary())
                    else: v=self.parse_expr()
                    entries.append((first,v,False))
                else:
                    entries.append((None,first,False))
            if not self.match(','): break
            if self.cur().type==closer: break
        return entries
    def parse_destructure_entries(self,closer):
        # inside list( or [ used as target, entries like key=>target, nested list/[ ], empty holes
        entries=[]
        if self.cur().type==closer: self.advance(); return entries
        while True:
            if self.cur().type==',' :
                entries.append((None,None)); self.advance(); continue
            if self.cur().type==closer: break
            first=self.parse_expr()
            if self.match('=>'):
                v=self.parse_expr(); entries.append((first,v))
            else: entries.append((None,first))
            if not self.match(','): break
            if self.cur().type==closer: break
        self.expect(closer); return entries
    def parse_match(self):
        line=self.cur().line; self.expect_kw('match'); self.expect('('); subj=None
        if self.cur().type!=')': subj=self.parse_expr()
        self.expect(')'); self.expect('{'); arms=[]
        while self.cur().type!='}' and not self.at_eof():
            if self.is_kw('default'):
                self.advance(); conds=None
            else:
                conds=[self.parse_expr()]
                while self.match(','):
                    if self.cur().type=='=>': break
                    conds.append(self.parse_expr())
            self.expect('=>'); result=self.parse_expr(); arms.append((conds,result))
            if not self.match(','): break
        self.expect('}'); return ('match',line,subj,arms)
    def parse_closure(self):
        line=self.cur().line; is_static=False; attrs=[]
        if self.is_kw('static'): self.advance(); is_static=True
        if self.is_kw('fn'):
            self.advance(); byref=bool(self.match('&')); params=self.parse_params(); ret=None
            if self.match(':'): ret=self.parse_type()
            self.expect('=>'); expr=self.parse_expr()
            func=PhpFunction(name='',params=params,body=expr,return_type=ret,byref_return=byref,namespace=self.current_namespace,file=self.filename,line=line,is_closure=True,is_arrow=True,is_static_closure=is_static,attributes=attrs)
            return ('closure',line,func,[])
        # function
        self.expect_kw('function'); byref=bool(self.match('&'))
        # anonymous has no name; if name present this is decl, but parse_statement routes decls away
        params=self.parse_params(); captures=[]
        if self.is_kw('use'):
            self.advance(); self.expect('(')
            if self.cur().type!=')':
                while True:
                    byr=bool(self.match('&')); vt=self.expect('VAR'); captures.append((vt.value,byr))
                    if not self.match(','): break
            self.expect(')')
        ret=None
        if self.match(':'): ret=self.parse_type()
        body=self.parse_block_statements()
        func=PhpFunction(name='',params=params,body=body,return_type=ret,byref_return=byref,namespace=self.current_namespace,file=self.filename,line=line,is_closure=True,is_arrow=False,is_static_closure=is_static,attributes=attrs)
        func.end_line=self.cur().line
        return ('closure',line,func,captures)
    def parse_new(self):
        line=self.cur().line; self.expect_kw('new')
        if self.is_kw('class'):
            # anonymous class
            anon_idx=self.anon_counter; self.anon_counter+=1
            anon_name=f'class@anonymous\x00{self.filename}:{line}${anon_idx}'
            self.advance(); args=[]
            if self.cur().type=='(': args=self.parse_call_args()
            if args=='FCC': args=[]
            # parse_class_body expects already consumed kind+name - replicate via manual call components: we need parse body after optional extends/implements, reuse parse_class_body by temporarily? It starts with backing/extends handling and expects '{' inside, good: kind=class, name=anon_name
            info=self.parse_class_body('class',anon_name,[],[],line,anon=True)
            info['name']=anon_name; info['simple_name']=anon_name
            return ('new_anon',line,info,args)
        # target
        target=None
        if self.cur().type=='VAR' or self.cur().type=='$':
            target=('expr',self.parse_unary())
        elif self.cur().type=='(':
            # Not standard unless variable class syntax new ($x) - parse paren expr
            self.advance(); e=self.parse_expr(); self.expect(')'); target=('expr',e)
        else:
            segs,abs_=self.parse_name_segments()
            if not segs: self.error(expecting='class name')
            _,res=self.resolve_name(segs,abs_,'class'); target=('class',res,'\\'.join(segs))
        args=[]
        if self.cur().type=='(':
            a=self.parse_call_args(); args=[] if a=='FCC' else a
        return ('new',line,target,args)

def parse_php_source(source, filename, start_in_php=False, short_open_tag=True):
    lx=Lexer(source,filename,start_in_php=start_in_php,short_open_tag=short_open_tag)
    toks=lx.tokenize()
    p=Parser(toks,filename); p._short_tag=short_open_tag
    try:
        prog=p.parse_program()
    except ParserError as e:
        raise ParseFatal(e.message, filename, e.line)
    return prog

