                while self.match(','): tnames.append(self.parse_resolved_class_name())
                adaptations=[]
                if self.cur().type=='{':
                    self.advance()
                    while self.cur().type!='}' and not self.at_eof():
                        adaptations.append(self.parse_trait_adaptation())
                    self.expect('}')
                else: self.expect(';')
                trait_uses.append((tnames,adaptations)); continue
