            vis=None; set_vis=None; static=False; abstract=False; final=False; readonly=False; var_kw=False
            while self.cur().type=='IDENT' and self.cur().value.lower() in ('public','protected','private','static','abstract','final','readonly','var'):
                w=self.advance().value.lower()
                if w in ('public','protected','private'):
                    # asymmetric: private(set) etc
                    if self.cur().type=='(' and self.peek(1).type=='IDENT' and self.peek(1).value.lower()=='set':
                        self.advance(); self.advance(); self.expect(')'); set_vis=w
                    else:
                        if vis is None: vis=w
                        else: set_vis=w  # e.g. public private(set) handled previous iteration? second visibility is set_vis
                elif w=='static': static=True
                elif w=='abstract': abstract=True
                elif w=='final': final=True
                elif w=='readonly': readonly=True
