        if isinstance(v,bool): return b'bool(true)\n' if v else b'bool(false)\n'
        if isinstance(v,int): return f'int({v})\n'.encode()
        if isinstance(v,float): return f'float({float_format_serialize(v,self.serialize_precision())})\n'.encode()
        if isinstance(v,bytes): return b'string('+str(len(v)).encode()+b') "'+v+b'"\n'
        if isinstance(v,PhpResource):
            t='Unknown' if v.closed else v.type; return f'resource({v.id}) of type ({t})\n'.encode()
        if isinstance(v,PhpArray):
            if id(v) in seen: return b'*RECURSION*\n'
            seen2=set(seen); seen2.add(id(v))
            out=f'array({len(v.data)}) {{\n'.encode()
            for k,c in v.data.items():
                out+=pad+b'  ['
                out+= (str(k).encode() if isinstance(k,int) else b'"'+k+b'"')
                out+=b']=>\n'+pad+b'  '
                if c.is_ref: out+=b'&'
                if c.value is UNINIT: out+=b'uninitialized\n'
                else: out+=self.var_dump_str(c.value,frame,line,indent+1,seen2)
            out+=pad+b'}\n'; return out
        if isinstance(v,PhpObject):
            if v.is_enum_case:
                return f'enum({v.class_name}::{v.enum_name})\n'.encode()
            if id(v) in seen: return b'*RECURSION*\n'
            seen2=set(seen); seen2.add(id(v))
            # Closure special dump
            if v.class_name.lower()=='closure':
                return self.dump_closure(v,indent,seen2,frame,line)
            items,debug_raw=self.get_dump_props(v,frame,line)
            count=sum(1 for k,c in items if not (isinstance(c,Cell) and c.value is UNINIT))
            out=f'object({v.class_name})#{v.object_id} ({count}) {{\n'.encode()
            for k,c in items:
                val=c.value if isinstance(c,Cell) else c
                isref=isinstance(c,Cell) and c.is_ref
                out+=pad+b'  ['
                if debug_raw:
                    out+=(str(k).encode() if isinstance(k,int) else b'"'+(k if isinstance(k,bytes) else bstr(k))+b'"')
                else:
                    disp,vis,priv=self.unmangle_prop_key(k)
                    out+=b'"'+disp+b'"'
                    if vis=='protected': out+=b':protected'
                    elif vis=='private': out+=b':"'+priv+b'":private'
                out+=b']=>\n'+pad+b'  '
                if isref: out+=b'&'
                if val is UNINIT:
                    # determine type if declared
                    ty='mixed'
                    disp,_,_=self.unmangle_prop_key(k)
                    pd=self.find_prop_def_for_display(v,disp)
                    if pd and pd.type: ty=pd.type
                    out+=f'uninitialized({ty})\n'.encode()
                else:
                    out+=self.var_dump_str(val,frame,line,indent+1,seen2)
            out+=pad+b'}\n'; return out
        if v is UNINIT: return b'uninitialized\n'
        return b'?\n'
    def dump_closure(self,obj,indent,seen,frame,line):
        pad=b'  '*indent
        func=obj.internal.get('func'); fcc=obj.internal.get('fcc')
        items=[]
        if fcc:
            fname=fcc.get('name',b''); items.append((b'function',Cell(bstr(fname))))
            params=PhpArray()
            fnobj=fcc.get('func')
            if fnobj:
                for p in fnobj.params:
                    params.set(bstr('$'+p.name), b'<required>' if not p.has_default and not p.variadic else b'<optional>')
            items.append((b'parameter',Cell(params)))
        elif func:
            loc=f'{{closure:{func.file}:{func.line}}}'
            items.append((b'name',Cell(bstr(loc)))); items.append((b'file',Cell(bstr(func.file)))); items.append((b'line',Cell(func.line)))
            # bound this / static vars? PHP 8.6 may show this if bound
            if func.this_binding is not None:
                items.append((b'this',Cell(func.this_binding)))
        else:
            items=list(obj.props.items())
        out=f'object({obj.class_name})#{obj.object_id} ({len(items)}) {{\n'.encode()
        for k,c in items:
            out+=pad+b'  ["'+k+b'"]=>\n'+pad+b'  '+self.var_dump_str(c.value,frame,line,indent+1,seen)
        out+=pad+b'}\n'; return out
    def find_prop_def_for_display(self,obj,name_bytes):
        # approximate
        try: nm=sstr(name_bytes)
        except: return None
        cls=self.classes.get(obj.class_name.lower())
        while cls:
            if nm in cls.prop_defs: return cls.prop_defs[nm]
            cls=self.classes.get(cls.parent.lower()) if cls.parent else None
        return None
    def print_r_str(self,v,frame=None,line=1,indent=b'',seen=None):
        if seen is None: seen=set()
        if v is None or v is NULLSAFE or v is False: return b''
        if v is True: return b'1'
        if isinstance(v,(int,bytes)): return self.to_string(v,frame,line)
        if isinstance(v,float): return php_float_to_bytes(v,self.precision())
        if isinstance(v,PhpResource): return f'Resource id #{v.id}'.encode()
        if isinstance(v,PhpObject) and v.is_enum_case:
            # print_r enum? test later; treat object
            pass
        if isinstance(v,PhpArray):
            if id(v) in seen: return b'Array\n *RECURSION*'
            seen2=set(seen); seen2.add(id(v))
            out=b'Array\n'+indent+b'(\n'
            for k,c in v.data.items():
                kk=str(k).encode() if isinstance(k,int) else k
                out+=indent+b'    ['+kk+b'] => '+self.print_r_str(c.value if c.value is not UNINIT else None,frame,line,indent+b'        ',seen2)+b'\n'
            out+=indent+b')\n'; return out
        if isinstance(v,PhpObject):
            if id(v) in seen: return f'{v.class_name} Object\n *RECURSION*'.encode()
            seen2=set(seen); seen2.add(id(v))
            items,debug_raw=self.get_dump_props(v,frame,line) if v.class_name.lower()!='closure' else ([],False)
            if v.class_name.lower()=='closure':
                items=[]  # print_r closure shows empty? approx
            out=f'{v.class_name} Object\n'.encode()+indent+b'(\n'
            for k,c in items:
                val=c.value if isinstance(c,Cell) else c
                if val is UNINIT: continue
                if debug_raw:
                    kk=str(k).encode() if isinstance(k,int) else (k if isinstance(k,bytes) else bstr(k))
                else:
                    disp,vis,priv=self.unmangle_prop_key(k); kk=disp
                    if vis=='protected': kk+=b':protected'
                    elif vis=='private': kk+=b':'+priv+b':private'
                out+=indent+b'    ['+kk+b'] => '+self.print_r_str(val,frame,line,indent+b'        ',seen2)+b'\n'
            out+=indent+b')\n'; return out
        return self.to_string(v,frame,line)
    def var_export_str(self,v,frame=None,line=1,indent=0,seen=None):
        if seen is None: seen=set()
        pad='  '*indent
        if v is None or v is NULLSAFE: return 'NULL'
        if v is True: return 'true'
        if v is False: return 'false'
        if isinstance(v,int): return str(v)
        if isinstance(v,float): return float_format_serialize(v,self.serialize_precision(),for_var_export=True)
        if isinstance(v,bytes):
            return "'"+sstr(v).replace('\\','\\\\').replace("'", "\\'")+"'"
        if isinstance(v,PhpResource): return 'NULL'
        if isinstance(v,PhpArray):
            if id(v) in seen: return 'NULL'
            seen2=set(seen); seen2.add(id(v))
            if not v.data: return "array (\n"+pad+")"
            out="array (\n"
            for k,c in v.data.items():
                kk=str(k) if isinstance(k,int) else self.var_export_str(k,frame,line,indent+1,seen2)
                out+=pad+'  '+kk+' => '+self.var_export_str(c.value,frame,line,indent+1,seen2)+",\n"
            out+=pad+")"; return out
        if isinstance(v,PhpObject):
            if v.is_enum_case: return f'{v.class_name}::{v.enum_name}'
            if v.class_name.lower()=='closure': return 'NULL'
            if id(v) in seen: return 'NULL'
            seen2=set(seen); seen2.add(id(v))
            items,debug_raw=self.get_dump_props(v,frame,line)
            arr="array (\n"
            for k,c in items:
                val=c.value if isinstance(c,Cell) else c
                if val is UNINIT: continue
                # var_export uses mangled keys as string keys
                kk=self.var_export_str(k if isinstance(k,bytes) else bstr(k),frame,line,indent+1,seen2) if not isinstance(k,int) else str(k)
                arr+=pad+'  '+kk+' => '+self.var_export_str(val,frame,line,indent+1,seen2)+",\n"
            arr+=pad+")"
            if v.class_name.lower()=='stdclass': return f'(object) {arr}'
            return f'{v.class_name}::__set_state({arr})'
        return 'NULL'

