    # internal setup
    def _params_from_info(self,plist):
        out=[]
        for p in plist or []:
            default=p.get('default','__NODEFAULT__')
            has=default!='__NODEFAULT__'
            dnode=self._default_node_from_data(default) if has else None
            # If optional but no default info, PHP internal may treat as null default in some contexts; keep has=True if optional and not variadic? Reflection num_required controls count check via function_info separately. For binding, omitted optional gives None
            out.append(Param(p.get('name',''),p.get('type'),bool(p.get('byref')),bool(p.get('variadic')),dnode,has))
        return out
    def _default_node_from_data(self,v):
        line=1
        if v is None: return ('null',line)
        if isinstance(v,bool): return ('bool',line,v)
        if isinstance(v,int): return ('int',line,v)
        if isinstance(v,float): return ('float',line,v)
        if isinstance(v,str): return ('string',line,bstr(v))
        if isinstance(v,dict) and '__enum__' in v:
            full=v['__enum__']; cls,case=full.rsplit(':',1); return ('class_const_fetch',line,('classname',line,cls,cls),('member',line,case))
        vals=self._data_value(v)
        return self._value_to_ast(vals,line)
    def _value_to_ast(self,v,line=1):
        if v is None: return ('null',line)
        if isinstance(v,bool): return ('bool',line,v)
        if isinstance(v,int): return ('int',line,v)
        if isinstance(v,float): return ('float',line,v)
        if isinstance(v,bytes): return ('string',line,v)
        if isinstance(v,PhpArray):
            entries=[]
            for k,c in v.data.items(): entries.append((self._value_to_ast(k,line),self._value_to_ast(c.value,line),False))
            return ('array',line,entries)
        return ('null',line)
    def setup_internal_classes(self):
        all_names=[]
        for n in _DATA.get('classes',[]): all_names.append(n)
        for n in _DATA.get('interfaces',[]):
            if n not in all_names: all_names.append(n)
        for n in _DATA.get('traits',[]): all_names.append(n)
        # create shells first
        for name in all_names:
            info=self.class_info.get(name,{})
            if isinstance(info,dict) and 'error' in info: info={}
            kind='interface' if info.get('is_interface') or name in _DATA.get('interfaces',[]) else ('trait' if info.get('is_trait') else 'class')
            cls=PhpClass(info.get('name',name),kind=kind,parent=info.get('parent'),interfaces=info.get('interfaces') or [],traits=info.get('traits') or [],internal=True,extension=info.get('extension') or False,file='',line=0)
            cls.abstract=bool(info.get('is_abstract')); cls.final=bool(info.get('is_final'))
            if info.get('is_enum'): cls.kind='enum'
            self.classes[cls.lower]=cls
        # populate members
        for name in all_names:
            info=self.class_info.get(name,{})
            if not isinstance(info,dict) or 'error' in info: continue
            cls=self.classes.get(name.lower())
            if not cls: continue
            # constants
            consts=info.get('constants') or {}
            if isinstance(consts,dict):
                for cname,cval in consts.items():
                    if cls.kind=='enum':
                        # case names only; backing special for PropertyHookType
                        cls.enum_cases[cname]=UNDEF  # lazy object, placeholder distinguished in get_enum_case
                        # store backing in internal map via const value marker below
                        if name=='PropertyHookType': bv=bstr(cname.lower())
                        else: bv=UNDEF
                        cls.constants[cname]=ConstDef(cname,('__enum_case__',bv),'public',False,None,cls.name)
                    else:
                        cls.constants[cname]=ConstDef(cname,self._data_value(cval),'public',False,None,cls.name)
            # properties
            props=info.get('properties') or {}
            defprops=info.get('default_props') or {}
            staticprops=info.get('static_props') or {}
            if isinstance(props,dict):
                for pname,pinfo in props.items():
                    vis='private' if pinfo.get('private') else ('protected' if pinfo.get('protected') else 'public')
                    has=bool(pinfo.get('has_default'))
                    dval=self._data_value(pinfo.get('default')) if has else UNDEF
                    if isinstance(defprops,dict) and pname in defprops:
                        has=True; dval=self._data_value(defprops.get(pname))
                    pd=PropDef(pname,vis,bool(pinfo.get('static')),pinfo.get('type'),None,has,copy_value(dval) if dval is not UNDEF else UNDEF,False,cls.name)
                    cls.prop_defs[pname]=pd
                    if pd.static:
                        sval=dval
                        if isinstance(staticprops,dict) and pname in staticprops: sval=self._data_value(staticprops.get(pname))
                        cls.static_props[pname]=Cell(copy_value(sval) if sval is not UNDEF else None)
            # methods own
            methods=info.get('methods') or {}
            if isinstance(methods,dict):
                for mname,minfo in methods.items():
                    vis='private' if minfo.get('private') else ('protected' if minfo.get('protected') else 'public')
                    params=self._params_from_info(minfo.get('params'))
                    fn=PhpFunction(name=mname,params=params,body=None,return_type=minfo.get('return'),namespace='',file='',line=0,is_internal=True,internal_fn=('internal_method',cls.name,mname),declaring_class=cls.name,extension=info.get('extension'))
                    md=MethodDef(mname,fn,vis,bool(minfo.get('static')),bool(minfo.get('abstract')),bool(minfo.get('final')),cls.name)
                    cls.own_methods[md.lower]=md
            if cls.name=='stdClass': cls.allow_dynamic=True
        # fill inherited methods recursively
        filled=set()
        def fill(cname,seen=None):
            if cname is None: return
            low=cname.lower()
            if low in filled: return
            if seen is None: seen=set()
            if low in seen: return
            seen.add(low)
            cls=self.classes.get(low)
            if not cls: return
            if cls.parent: fill(cls.parent,seen)
            methods={}
            if cls.parent and self.classes.get(cls.parent.lower()):
                methods.update(self.classes[cls.parent.lower()].methods)
            # interfaces methods as abstract placeholders if not present
            for iface in cls.interfaces:
                ic=self.classes.get(iface.lower())
                if ic:
                    fill(iface,seen)
                    for k,v in ic.methods.items():
                        if k not in methods: methods[k]=v
            methods.update(cls.own_methods)
            cls.methods=methods
            filled.add(low)
        for n in list(self.classes.keys()): fill(n)
        # enum interfaces auto
        for cls in self.classes.values():
            if cls.kind=='enum' and 'UnitEnum' not in cls.interfaces: cls.interfaces.append('UnitEnum')
    def setup_internal_functions_placeholder(self):
        for fname in _DATA.get('functions',[]):
            info=self.function_info.get(fname,{})
            params=self._params_from_info(info.get('params') if isinstance(info,dict) else [])
            fn=PhpFunction(name=fname,params=params,body=None,return_type=info.get('return') if isinstance(info,dict) else None,file='',line=0,is_internal=True,internal_fn=('stub',fname),extension=info.get('extension') if isinstance(info,dict) else None)
            self.functions[fname.lower()]=fn
    def register_internal_function(self,name,pyfn):
        low=name.lower()
        existing=self.functions.get(low)
        if existing and existing.is_internal:
            existing.internal_fn=pyfn
        else:
            fn=PhpFunction(name=name,params=[],is_internal=True,internal_fn=pyfn)
            self.functions[low]=fn
    # trace/throwables
    def capture_trace(self,frame=None,line=1,extra=None):
        entries=[]
        if extra: entries.append(extra)
        frames=self.get_frames()
        ignore_args=self.ini_bool('zend.exception_ignore_args',False)
        for fr in reversed(frames):
            if fr.is_main: continue
            if fr.func_name in ('',None) and fr.func is None: continue
            e={'file':bstr(fr.call_file) if fr.call_file else None,'line':fr.call_line,'function':bstr(fr.func_name or '')}
            if fr.class_name: e['class']=fr.class_name; e['type']=bstr(fr.call_type or '->')
            if not ignore_args:
                arr=PhpArray()
                for a in (fr.args or []): arr.append(copy_value(a) if isinstance(a,PhpArray) else a)
                e['args']=arr
            entries.append(e)
        return entries
    def trace_to_array(self,trace):
        out=PhpArray()
        for e in trace:
            ea=PhpArray()
            if e.get('file') is not None: ea.set(b'file',e['file'])
            if e.get('line') is not None: ea.set(b'line',e['line'])
            ea.set(b'function',e.get('function',b''))
            if e.get('class'): ea.set(b'class',bstr(e['class'])); ea.set(b'type',bstr(e.get('type','->')))
            if 'object' in e: ea.set(b'object',e['object'])
            if 'args' in e: ea.set(b'args',e['args'])
            out.append(ea)
        return out
    def trace_arg_repr(self,v):
        if v is None: return 'NULL'
        if v is True: return 'true'
        if v is False: return 'false'
        if isinstance(v,int): return str(v)
        if isinstance(v,float): return float_format_serialize(v,self.serialize_precision())
        if isinstance(v,bytes):
            maxlen=self.ini_int('zend.exception_string_param_max_len',15)
            data=v
            if len(data)>maxlen: data=data[:maxlen]+b'...'
            return "'"+sstr(data)+"'"
        if isinstance(v,PhpArray): return 'Array'
        if isinstance(v,PhpObject): return f'Object({v.class_name})'
        if isinstance(v,PhpResource): return f'Resource id #{v.id}'
        return '?'
    def trace_to_string(self,trace):
        lines=[]
        for i,e in enumerate(trace):
            func=sstr(e.get('function',b''))
            if e.get('class'): func=sstr(e['class'])+sstr(e.get('type','->'))+func
            args=''
            if 'args' in e and isinstance(e['args'],PhpArray):
                args=', '.join(self.trace_arg_repr(c.value) for c in e['args'].data.values())
            if e.get('file') is not None:
                lines.append(f"#{i} {sstr(e['file'])}({e.get('line',0)}): {func}({args})")
            else:
                lines.append(f"#{i} [internal function]: {func}({args})")
        lines.append(f"#{len(trace)} {{main}}")
        return '\n'.join(lines)
    def exception_root_class(self,clsname):
        cur=clsname
        seen=set()
        while cur and cur.lower() not in seen:
            seen.add(cur.lower())
            if cur.lower() in ('exception','error'): return self.classes[cur.lower()].name
            c=self.classes.get(cur.lower()); cur=c.parent if c else None
        return 'Exception'
    def init_throwable_props(self,obj,message,code,file,line,trace,previous):
        root=self.exception_root_class(obj.class_name)
        # internal storage
        obj.internal['exception']={'message':bstr(message),'code':code,'file':bstr(file),'line':line,'trace':trace,'previous':previous}
        # props in declared order (initialize all props first may have been done by create; set specific keys preserving order from hierarchy init)
        def setprop(mangled,val):
            c=obj.props.get(mangled)
            if c is None: obj.props[mangled]=Cell(val)
            else: c.value=val
        setprop(b'\x00*\x00message',bstr(message))
        setprop(b'\x00'+bstr(root)+b'\x00string',b'')
        setprop(b'\x00*\x00code',code)
        setprop(b'\x00*\x00file',bstr(file))
        setprop(b'\x00*\x00line',line)
        setprop(b'\x00'+bstr(root)+b'\x00trace',self.trace_to_array(trace))
        setprop(b'\x00'+bstr(root)+b'\x00previous',previous)
    def create_throwable(self,class_name,message,frame=None,line=1,code=0,previous=None,extra_trace=None,file_override=None,line_override=None):
        cls=self.classes.get(class_name.lower().lstrip('\\'))
        canon=cls.name if cls else class_name
        obj=self.instantiate_no_ctor(canon,frame,line)
        trace=self.capture_trace(frame,line,extra=extra_trace)
        file=file_override if file_override is not None else (frame.file if frame else '')
        ln=line_override if line_override is not None else line
        self.init_throwable_props(obj,message,code,file,ln,trace,previous)
        return obj
    def throw_error(self,class_name,message,frame=None,line=1,code=0,previous=None,extra_trace=None,file_override=None,line_override=None):
        raise PhpThrown(self.create_throwable(class_name,message,frame,line,code,previous,extra_trace,file_override,line_override))
    def fatal(self,message,frame=None,line=1):
        trace=self.capture_trace(frame,line) if frame else []
        raise PhpFatal(message, frame.file if frame else '', line, trace=trace)
    def throwable_to_string(self,obj,frame=None,line=1):
        # __toString for Exception/Error default format
        ex=obj.internal.get('exception') if isinstance(obj,PhpObject) else None
        if ex is None:
            # try read props (user exception created via constructor will have internal set by ctor handler); if not, construct from props
            msg=b''; file=b''; ln=0; trace=[]
            try: msg=self.get_property(obj,b'message',frame,line)
            except Exception: pass
            return f"{obj.class_name}: {sstr(msg)} in :0\nStack trace:\n#0 {{main}}"
        msg=sstr(ex.get('message',b'')); file=sstr(ex.get('file',b'')); ln=ex.get('line',0)
        s=f"{obj.class_name}: {msg} in {file}:{ln}\nStack trace:\n{self.trace_to_string(ex.get('trace',[]))}"
        prev=ex.get('previous')
        if isinstance(prev,PhpObject):
            s+=f"\n\nNext {self.throwable_to_string(prev,frame,line)}"
        return s
    # comparisons
    def loose_equal(self,a,b,frame=None,line=1):
        if a is NULLSAFE: a=None
        if b is NULLSAFE: b=None
        if isinstance(a,PhpArray) and isinstance(b,PhpArray):
            if len(a.data)!=len(b.data): return False
            for k,c in a.data.items():
                bc=b.data.get(k)
                if bc is None: return False
                if not self.loose_equal(c.value,bc.value,frame,line): return False
            return True
        if isinstance(a,PhpObject) and isinstance(b,PhpObject):
            if a.class_name.lower()!=b.class_name.lower(): return False
            if a.is_enum_case or b.is_enum_case: return a is b
            if len(a.props)!=len(b.props): return False
            for k,c in a.props.items():
                bc=b.props.get(k)
                if bc is None: return False
                if c.value is UNINIT or bc.value is UNINIT: 
                    if c.value is not bc.value: return False
                    continue
                if not self.loose_equal(c.value,bc.value,frame,line): return False
            # internal objects comparison fallback: DateTime etc compare internal timestamps if present
            if a.internal and b.internal:
                # if both have datetime ts
                if 'timestamp' in a.internal and 'timestamp' in b.internal: return a.internal['timestamp']==b.internal['timestamp']
            return True
        if isinstance(a,PhpResource) and isinstance(b,PhpResource): return a.id==b.id
        return self.compare_loose(a,b,frame,line)==0
    def strict_equal(self,a,b):
