    def trace_arg_repr(self,v):
        if v is None: return 'NULL'
        if v is True: return 'true'
        if v is False: return 'false'
        if isinstance(v,int): return str(v)
        if isinstance(v,float): return float_format_serialize(v,self.serialize_precision())
        if isinstance(v,bytes):
            maxlen=self.ini_int('zend.exception_string_param_max_len',15)
            data=v
            if len(data)>maxlen: data=data[:maxlen]+b'...'
            return "'"+sstr(data)+"'"
        if isinstance(v,PhpArray): return 'Array'
        if isinstance(v,PhpObject): return f'Object({v.class_name})'
        if isinstance(v,PhpResource): return f'Resource id #{v.id}'
        return '?'
    def trace_to_string(self,trace):
        lines=[]
        for i,e in enumerate(trace):
            func=sstr(e.get('function',b''))
            if e.get('class'): func=sstr(e['class'])+sstr(e.get('type','->'))+func
            args=''
