                args=', '.join(self.trace_arg_repr(c.value) for c in e['args'].data.values())
            if e.get('file') is not None:
                lines.append(f"#{i} {sstr(e['file'])}({e.get('line',0)}): {func}({args})")
            else:
                lines.append(f"#{i} [internal function]: {func}({args})")
