    def throw_error(self,class_name,message,frame=None,line=1,code=0,previous=None,extra_trace=None,file_override=None,line_override=None):
        raise PhpThrown(self.create_throwable(class_name,message,frame,line,code,previous,extra_trace,file_override,line_override))
    def fatal(self,message,frame=None,line=1):
        trace=self.capture_trace(frame,line) if frame else []
        raise PhpFatal(message, frame.file if frame else '', line, trace=trace)
    def throwable_to_string(self,obj,frame=None,line=1):
        # __toString for Exception/Error default format
        ex=obj.internal.get('exception') if isinstance(obj,PhpObject) else None
        if ex is None:
            # try read props (user exception created via constructor will have internal set by ctor handler); if not, construct from props
            msg=b''; file=b''; ln=0; trace=[]
            try: msg=self.get_property(obj,b'message',frame,line)
            except Exception: pass
            return f"{obj.class_name}: {sstr(msg)} in :0\nStack trace:\n#0 {{main}}"
        msg=sstr(ex.get('message',b'')); file=sstr(ex.get('file',b'')); ln=ex.get('line',0)
        s=f"{obj.class_name}: {msg} in {file}:{ln}\nStack trace:\n{self.trace_to_string(ex.get('trace',[]))}"
        prev=ex.get('previous')
        if isinstance(prev,PhpObject):
            s+=f"\n\nNext {self.throwable_to_string(prev,frame,line)}"
        return s
    # comparisons
    def loose_equal(self,a,b,frame=None,line=1):
        if a is NULLSAFE: a=None
        if b is NULLSAFE: b=None
        if isinstance(a,PhpArray) and isinstance(b,PhpArray):
            if len(a.data)!=len(b.data): return False
            for k,c in a.data.items():
                bc=b.data.get(k)
                if bc is None: return False
                if not self.loose_equal(c.value,bc.value,frame,line): return False
            return True
        if isinstance(a,PhpObject) and isinstance(b,PhpObject):
            if a.class_name.lower()!=b.class_name.lower(): return False
            if a.is_enum_case or b.is_enum_case: return a is b
            if len(a.props)!=len(b.props): return False
            for k,c in a.props.items():
                bc=b.props.get(k)
                if bc is None: return False
                if c.value is UNINIT or bc.value is UNINIT: 
                    if c.value is not bc.value: return False
                    continue
                if not self.loose_equal(c.value,bc.value,frame,line): return False
            # internal objects comparison fallback: DateTime etc compare internal timestamps if present
            if a.internal and b.internal:
                # if both have datetime ts
                if 'timestamp' in a.internal and 'timestamp' in b.internal: return a.internal['timestamp']==b.internal['timestamp']
            return True
        if isinstance(a,PhpResource) and isinstance(b,PhpResource): return a.id==b.id
        return self.compare_loose(a,b,frame,line)==0
    def strict_equal(self,a,b):
        if a is NULLSAFE: a=None
        if b is NULLSAFE: b=None
        if type(a) is not type(b):
            # PHP int/float distinct already diff types; bool vs int diff Python types
            return False
        if isinstance(a,PhpArray):
            ak=list(a.data.keys()); bk=list(b.data.keys())
            if ak!=bk: return False
            for k in ak:
                if not self.strict_equal(a.data[k].value,b.data[k].value): return False
            return True
        if isinstance(a,PhpObject): return a is b
        if isinstance(a,PhpResource): return a.id==b.id and not a.closed and not b.closed
        if isinstance(a,float): return a==b  # NAN false
        return a==b
    def compare_numbers(self,a,b):
        if isinstance(a,float) and math.isnan(a): return 1
        if isinstance(b,float) and math.isnan(b): return -1 if False else 1
        if a<b: return -1
        if a>b: return 1
        return 0
    def compare_loose(self,a,b,frame=None,line=1):
        if a is NULLSAFE: a=None
        if b is NULLSAFE: b=None
        # bool either (except? both strings/numbers handled if no bool)
        if isinstance(a,bool) or isinstance(b,bool):
            ba=truthy(a); bb=truthy(b); return (ba>bb)-(ba<bb)
        if a is None or b is None:
            if a is None and b is None: return 0
            if a is None:
                if isinstance(b,bytes): return self.compare_loose(b'',b,frame,line)
                if isinstance(b,PhpArray): return self.compare_loose(False,truthy(b),frame,line)
                if isinstance(b,PhpObject): return -1
                # number/resource
                bb=truthy(b); return (False>bb)-(False<bb)
            else:
                if isinstance(a,bytes): return self.compare_loose(a,b'',frame,line)
                if isinstance(a,PhpArray): return self.compare_loose(truthy(a),False,frame,line)
                if isinstance(a,PhpObject): return 1
                ba=truthy(a); return (ba>False)-(ba<False)
        if isinstance(a,PhpArray) and isinstance(b,PhpArray):
            if len(a.data)!=len(b.data): return -1 if len(a.data)<len(b.data) else 1
            # compare in order of a keys
            for k,c in a.data.items():
                bc=b.data.get(k)
                if bc is None: return 1
                cmp=self.compare_loose(c.value,bc.value,frame,line)
                if cmp!=0: return cmp
            return 0
        if isinstance(a,PhpArray) or isinstance(b,PhpArray):
            return 1 if isinstance(a,PhpArray) else -1
        if isinstance(a,PhpObject) and isinstance(b,PhpObject):
            if self.loose_equal(a,b,frame,line): return 0
            # DateTime comparisons by timestamp
            if 'timestamp' in a.internal and 'timestamp' in b.internal: return self.compare_numbers(a.internal['timestamp'],b.internal['timestamp'])
            # fallback compare props count then values
            if len(a.props)!=len(b.props): return -1 if len(a.props)<len(b.props) else 1
            for k,c in a.props.items():
                bc=b.props.get(k)
                if bc is None: return 1
                cmp=self.compare_loose(c.value,bc.value,frame,line)
                if cmp: return cmp
            return 0
        if isinstance(a,PhpObject) or isinstance(b,PhpObject):
            # Stringable to string comparison if other string/number? PHP: object with __toString compared to string uses string? For ==  string/object
            obj=a if isinstance(a,PhpObject) else b; other=b if obj is a else a
            if isinstance(other,(bytes,int,float)) and self.find_method(obj.class_name,'__toString'):
                s=self.to_string(obj,frame,line)
                return self.compare_loose(s,other,frame,line) if obj is a else self.compare_loose(other,s,frame,line)
            return 1 if isinstance(a,PhpObject) else -1
        if isinstance(a,PhpResource): a=a.id
        if isinstance(b,PhpResource): b=b.id
        if isinstance(a,bytes) and isinstance(b,bytes):
            if is_numeric_string(a) and is_numeric_string(b):
                av,_=parse_numeric_string(a); bv,_=parse_numeric_string(b); return self.compare_numbers(av,bv)
            return (a>b)-(a<b)
        if isinstance(a,bytes) and isinstance(b,(int,float)):
            if is_numeric_string(a):
                av,_=parse_numeric_string(a); return self.compare_numbers(av,b)
            bs=self.to_string(b,frame,line); return (a>bs)-(a<bs)
        if isinstance(b,bytes) and isinstance(a,(int,float)):
            if is_numeric_string(b):
                bv,_=parse_numeric_string(b); return self.compare_numbers(a,bv)
            astr=self.to_string(a,frame,line); return (astr>b)-(astr<b)
        if isinstance(a,(int,float)) and isinstance(b,(int,float)): return self.compare_numbers(a,b)
        # fallback string
        astr=self.to_string(a,frame,line); bstrv=self.to_string(b,frame,line); return (astr>bstrv)-(astr<bstrv)
    # dump helpers
    def unmangle_prop_key(self,k):
        # returns (display_name_bytes, visibility_info_str_or_None, private_class)
        if isinstance(k,bytes) and k.startswith(b'\x00*\x00'): return (k[3:],'protected',None)
        if isinstance(k,bytes) and k.startswith(b'\x00'):
            parts=k.split(b'\x00')
            if len(parts)>=3: return (parts[2],'private',parts[1])
        return (k,None,None)
    def mangle_prop_key(self,name_bytes,visibility,declaring_class):
        if visibility=='private': return b'\x00'+bstr(declaring_class or '')+b'\x00'+name_bytes
        if visibility=='protected': return b'\x00*\x00'+name_bytes
        return name_bytes
    def get_dump_props(self,obj,frame=None,line=1):
        # __debugInfo
        if self.find_method(obj.class_name,'__debugInfo'):
            try:
                res=self.call_method_values(obj,'__debugInfo',[],frame,line)
                if isinstance(res,PhpArray):
                    # keys are as-is (not mangled)
                    return list(res.data.items()), True
            except PhpThrown:
                raise
            except Exception:
                pass
        provider=self.state.get('dump_providers',{}).get(obj.class_name.lower()) if isinstance(self.state.get('dump_providers',{}),dict) else None
        if provider:
            try:
                items=provider(self,obj,frame,line)
                if items is not None: return items, False
            except PhpThrown: raise
            except Exception: pass
        return list(obj.props.items()), False
    def var_dump_str(self,v,frame=None,line=1,indent=0,seen=None):
        if seen is None: seen=set()
        pad=b'  '*indent
        if v is None or v is NULLSAFE: return b'NULL\n'
        if isinstance(v,bool): return b'bool(true)\n' if v else b'bool(false)\n'
        if isinstance(v,int): return f'int({v})\n'.encode()
        if isinstance(v,float): return f'float({float_format_serialize(v,self.serialize_precision())})\n'.encode()
        if isinstance(v,bytes): return b'string('+str(len(v)).encode()+b') "'+v+b'"\n'
        if isinstance(v,PhpResource):
            t='Unknown' if v.closed else v.type; return f'resource({v.id}) of type ({t})\n'.encode()
        if isinstance(v,PhpArray):
            if id(v) in seen: return b'*RECURSION*\n'
            seen2=set(seen); seen2.add(id(v))
            out=f'array({len(v.data)}) {{\n'.encode()
            for k,c in v.data.items():
                out+=pad+b'  ['
                out+= (str(k).encode() if isinstance(k,int) else b'"'+k+b'"')
                out+=b']=>\n'+pad+b'  '
                if c.is_ref: out+=b'&'
                if c.value is UNINIT: out+=b'uninitialized\n'
                else: out+=self.var_dump_str(c.value,frame,line,indent+1,seen2)
            out+=pad+b'}\n'; return out
        if isinstance(v,PhpObject):
            if v.is_enum_case:
                return f'enum({v.class_name}::{v.enum_name})\n'.encode()
            if id(v) in seen: return b'*RECURSION*\n'
            seen2=set(seen); seen2.add(id(v))
            # Closure special dump
            if v.class_name.lower()=='closure':
                return self.dump_closure(v,indent,seen2,frame,line)
            items,debug_raw=self.get_dump_props(v,frame,line)
            count=sum(1 for k,c in items if not (isinstance(c,Cell) and c.value is UNINIT))
            out=f'object({v.class_name})#{v.object_id} ({count}) {{\n'.encode()
            for k,c in items:
                val=c.value if isinstance(c,Cell) else c
                isref=isinstance(c,Cell) and c.is_ref
                out+=pad+b'  ['
                if debug_raw:
                    out+=(str(k).encode() if isinstance(k,int) else b'"'+(k if isinstance(k,bytes) else bstr(k))+b'"')
                else:
                    disp,vis,priv=self.unmangle_prop_key(k)
                    out+=b'"'+disp+b'"'
                    if vis=='protected': out+=b':protected'
                    elif vis=='private': out+=b':"'+priv+b'":private'
                out+=b']=>\n'+pad+b'  '
