        return b'?\n'
    def dump_closure(self,obj,indent,seen,frame,line):
        pad=b'  '*indent
        func=obj.internal.get('func'); fcc=obj.internal.get('fcc')
        items=[]
        if fcc:
            fname=fcc.get('name',b''); items.append((b'function',Cell(bstr(fname))))
