            items=list(obj.props.items())
        out=f'object({obj.class_name})#{obj.object_id} ({len(items)}) {{\n'.encode()
        for k,c in items:
            out+=pad+b'  ["'+k+b'"]=>\n'+pad+b'  '+self.var_dump_str(c.value,frame,line,indent+1,seen)
        out+=pad+b'}\n'; return out
