    # class helpers
    def class_lookup(self,name):
        if not name: return None
        return self.classes.get(str(name).strip('\\').lower())
    def trigger_autoload(self,class_name,frame=None,line=1):
        if self.class_lookup(class_name): return True
        key=str(class_name).lower().lstrip('\\')
        if self.state.get('_autoloading')==key: return False
        funcs=list(self.autoload_functions)
        # classic __autoload function
        if '__autoload' in self.functions and not any(True for _ in funcs):
            funcs=[b'__autoload']
        for fn in funcs:
            self.state['_autoloading']=key
            try: self.call_callable_values(fn,[bstr(class_name)],frame,line)
            except PhpThrown: 
                self.state['_autoloading']=None; raise
            except Exception: pass
            self.state['_autoloading']=None
            if self.class_lookup(class_name): return True
        return False
    def get_class_or_throw(self,name,frame,line,expected='Class'):
        cls=self.class_lookup(name)
        if cls is None:
            self.trigger_autoload(name,frame,line); cls=self.class_lookup(name)
        if cls is None:
            self.throw_error('Error',f'{expected} "{name}" not found',frame,line)
        return cls
    def class_ancestors(self,cls):
        out=[]; cur=cls; seen=set()
        while cur and cur.lower not in seen:
            out.append(cur); seen.add(cur.lower)
            cur=self.class_lookup(cur.parent) if cur.parent else None
        return out
    def all_interfaces_of(self,cls):
        names=[]; seen=set()
        def add_iface(iname):
            ic=self.class_lookup(iname)
            if not ic: return
            if ic.lower in seen: return
            seen.add(ic.lower); names.append(ic.name)
            for p in ic.interfaces: add_iface(p)
            if ic.parent: add_iface(ic.parent)
        for c in self.class_ancestors(cls):
            for i in c.interfaces: add_iface(i)
