        parts=[]; depth=0; cur=''
        for ch in s:
            if ch=='(': depth+=1; cur+=ch
            elif ch==')': depth-=1; cur+=ch
            elif ch=='|' and depth==0: parts.append(cur); cur=''
            else: cur+=ch
