        if low=='true': return v is True
        if low=='bool': return isinstance(v,bool)
        if low=='int': return isinstance(v,int) and not isinstance(v,bool)
        if low=='float': return isinstance(v,float) or (isinstance(v,int) and not isinstance(v,bool))
        if low=='string': return isinstance(v,bytes)
        if low=='array': return isinstance(v,PhpArray)
        if low=='object': return isinstance(v,PhpObject)
        if low=='iterable': return isinstance(v,PhpArray) or (isinstance(v,PhpObject) and self.is_a_obj(v,'Traversable'))
        if low=='callable': return self.is_callable_value(v,False,frame,line)
        if low=='resource': return isinstance(v,PhpResource)
        if low=='void' or low=='never': return False
        # class/interface
        return isinstance(v,PhpObject) and self.is_a_obj(v,str(atom))
    def coerce_value_to_type(self,v,type_str,frame,line,strict=False,internal_target=False,scope_class=None,called_class=None,error_builder=None):
        if type_str is None or str(type_str).lower()=='mixed': return v
        texpr=self.parse_type_expr(type_str)
        if self.type_matches(v,texpr,frame,line,scope_class,called_class):
            # float widening convert int->float if exact atom float and int
            if str(type_str).strip().lower()=='float' and isinstance(v,int) and not isinstance(v,bool): return float(v)
            return v
        # nullable mismatch null handled by matches
        if v is None and internal_target:
            # emit deprecated handled by caller (it knows param number); coerce to zero of first scalar type
            # return marker tuple? caller checks None internal before calling.
            pass
        if strict:
            err=error_builder(self.type_given_name(v)) if error_builder else f'must be of type {type_str}, {self.type_given_name(v)} given'
            self.throw_error('TypeError',err,frame,line)
        # coercive attempts based on type expr preference
        # gather atoms in order
        atoms=[]
        def collect(t):
            if t[0] in ('union','inter'):
                for x in t[1]: collect(x)
            elif t[0]=='nullable': collect(t[1])
            else: atoms.append(t[1])
        collect(texpr)
        # if intersection, no coercion
        if texpr[0]=='inter':
            err=error_builder(self.type_given_name(v)) if error_builder else f'must be of type {type_str}, {self.type_given_name(v)} given'; self.throw_error('TypeError',err,frame,line)
        # exact class etc no coercion except scalars
        for atom_raw in atoms:
            atom=self.resolve_type_atom(atom_raw,frame,scope_class,called_class); low=str(atom).lower()
            try:
                if low=='int':
                    if isinstance(v,bool): return 1 if v else 0
                    if isinstance(v,float): return trunc_int_from_float(v)
                    if isinstance(v,bytes) and is_numeric_string(v):
                        val,_=parse_numeric_string(v); return trunc_int_from_float(val) if isinstance(val,float) else val
                elif low=='float':
                    if isinstance(v,(int,bool)): return float(self.to_int(v,frame,line))
                    if isinstance(v,bytes) and is_numeric_string(v): return self.to_float(v,frame,line)
                elif low=='string':
                    if isinstance(v,(int,float,bool)): return self.to_string(v,frame,line)
                    if isinstance(v,PhpObject) and self.find_method(v.class_name,'__toString'): return self.to_string(v,frame,line)
                elif low=='bool':
                    if isinstance(v,(int,float,bytes)): return truthy(v)
                elif low=='array':
                    pass
                elif low=='callable':
                    if self.is_callable_value(v,False,frame,line): return v
            except PhpThrown:
                raise
        err=error_builder(self.type_given_name(v)) if error_builder else f'must be of type {type_str}, {self.type_given_name(v)} given'
        self.throw_error('TypeError',err,frame,line)
