        if not pd.type: return value
        def eb(given): return f'Cannot assign {given} to property {pd.declaring_class}::${pd.name} of type {pd.type}'
        return self.coerce_value_to_type(value,pd.type,frame,line,strict=False,scope_class=pd.declaring_class,called_class=frame.called_class if frame else None,error_builder=eb)
