    def member_name_bytes(self,name_node,frame,line):
        if name_node[0]=='member': return bstr(name_node[2])
        if name_node[0]=='var':
            v=self.eval_expr(name_node,frame); return self.to_string(v,frame,line)
        v=self.eval_expr(name_node,frame); return self.to_string(v,frame,line)
    def resolve_class_base(self,node,frame,line):
        # returns (class_name_requested_or_canonical, called_class_name, forwarding)
        if node[0]=='classname':
            resolved=node[2]; disp=node[3] if len(node)>3 else resolved
            low=str(resolved).lower()
            if low=='self':
                return (frame.scope_class or '', frame.called_class or frame.scope_class or '', True)
            if low=='static':
                return (frame.called_class or frame.scope_class or '', frame.called_class or frame.scope_class or '', True)
            if low=='parent':
                sc=self.class_lookup(frame.scope_class or ''); return ((sc.parent if sc else '') or '', frame.called_class or (sc.name if sc else ''), True)
            cls=self.class_lookup(resolved)
            return ((cls.name if cls else str(resolved)), (cls.name if cls else str(resolved)), False)
        v=self.eval_expr_raw(node,frame)
        if v is NULLSAFE: return ('','',False)
        if isinstance(v,PhpObject): return (v.class_name,v.class_name,False)
        if isinstance(v,bytes):
            nm=sstr(v).lstrip('\\'); cls=self.class_lookup(nm); return ((cls.name if cls else nm),(cls.name if cls else nm),False)
        self.throw_error('Error',f'Class name must be a valid object or a string',frame,line)
    def get_class_constant(self,cls,name_str,frame,line):
        # enum cases
        if name_str in cls.enum_cases:
            return self.get_enum_case(cls,name_str,frame,line)
        # search ancestors and interfaces
        candidates=[]
        for c in self.class_ancestors(cls): candidates.append(c)
        for iname in self.all_interfaces_of(cls):
            ic=self.class_lookup(iname)
            if ic: candidates.append(ic)
        if cls.kind=='interface':
            for iname in cls.interfaces:
                ic=self.class_lookup(iname)
                if ic: candidates.append(ic)
        for c in candidates:
            cd=c.constants.get(name_str)
            if cd is not None:
                if not self.visibility_accessible(cd.visibility,cd.declaring_class or c.name,frame.scope_class if frame else None,cls.name):
                    self.throw_error('Error',f'Cannot access {cd.visibility} constant {c.name}::{name_str}',frame,line)
                if isinstance(cd.value,tuple) and cd.value and cd.value[0]=='__enum_case__':
                    # parent enum? constants inherited from interface etc
                    return self.get_enum_case(c,name_str,frame,line)
                if cd.value is UNDEF and cd.node is not None:
                    cd.value=self.eval_const_expr(cd.node,frame,line,scope_class=c.name)
