        if obj.is_enum_case:
            if name_str=='name': return bstr(obj.enum_name)
            if name_str=='value' and obj.enum_value is not UNDEF: return obj.enum_value
        pd=self.find_prop_def(obj.class_name,name_str,frame.scope_class if frame else None)
        if pd is not None:
            if not self.visibility_accessible(pd.visibility,pd.declaring_class,frame.scope_class if frame else None,obj.class_name):
                # magic __get may handle inaccessible
                if self.find_method(obj.class_name,'__get'):
                    return self.call_method_values(obj,'__get',[name_bytes],frame,line,internal_system=True)
                self.throw_error('Error',f'Cannot access {pd.visibility} property {pd.declaring_class}::${name_str}',frame,line)
            if pd.hooks and 'get' in pd.hooks and pd.hooks.get('get') is not None:
                return self.invoke_property_hook(obj,pd,'get',None,frame,line)
            key=self.mangle_prop_key(name_bytes,pd.visibility,pd.declaring_class)
            cell=obj.props.get(key)
