        if cls:
            for c in self.class_ancestors(cls):
                if name_str in c.prop_defs: any_pd=c.prop_defs[name_str]; break
        if self.find_method(obj.class_name,'__get'):
            return self.call_method_values(obj,'__get',[name_bytes],frame,line,internal_system=True)
        if any_pd:
            self.throw_error('Error',f'Cannot access {any_pd.visibility} property {any_pd.declaring_class}::${name_str}',frame,line)
        self.warn(f'Undefined property: {obj.class_name}::${name_str}',frame,line); return None
    def invoke_property_hook(self,obj,pd,which,value,frame,line):
        hook=pd.hooks.get(which)
        if hook is None: return None
        # create frame like method on obj
        env=Env(self,False)
        fr=Frame(func_name=f'{pd.name}::{which}',func=None,env=env,file=frame.file if frame else '',line=line,call_file=frame.file if frame else '',call_line=line,this_obj=obj,scope_class=pd.declaring_class,called_class=obj.class_name,namespace='')
        if which=='set':
            params,body=hook
            if params: env.set_value(params[0].name,value)
            else: env.set_value('value',value)
            if body is None: return None
            kind,node=body
        else:
            kind,node=hook
        self.push_frame(fr)
        try:
            if kind=='expr': return self.eval_expr(node,fr)
            else:
                try: self.exec_block(node,fr)
                except ReturnSignal as r: return r.value
                return None
        finally: self.pop_frame()
