        pd=self.find_prop_def(obj.class_name,name_str,frame.scope_class if frame else None)
        if pd is not None:
            if not self.visibility_accessible(pd.set_visibility or pd.visibility,pd.declaring_class,frame.scope_class if frame else None,obj.class_name):
                if self.find_method(obj.class_name,'__set'):
                    self.call_method_values(obj,'__set',[name_bytes,value],frame,line,internal_system=True); return value
                # readonly visibility messages may differ; if readonly, appropriate msg below if set vis is public but readonly
                self.throw_error('Error',f'Cannot access {pd.set_visibility or pd.visibility} property {pd.declaring_class}::${name_str}',frame,line)
            if pd.hooks and 'set' in pd.hooks:
                self.invoke_property_hook(obj,pd,'set',value,frame,line); return value
            key=self.mangle_prop_key(name_bytes,pd.visibility,pd.declaring_class)
            cell=obj.props.get(key)
