                v=self.eval_expr(expr,frame)
                if isinstance(v,PhpArray):
                    for k,c in list(v.data.items()):
                        if isinstance(k,int):
                            if seen_named: raise PhpFatal('Cannot use positional argument after named argument',frame.file if frame else '',line,trace=self.capture_trace(frame,line))
                            raw.append((None,c.value,None,c))
                        else:
                            seen_named=True; raw.append((sstr(k),c.value,None,c))
                elif isinstance(v,PhpObject) and self.is_a_obj(v,'Traversable'):
                    for k,val,cell in self.iterate_items(v,frame,line):
                        if isinstance(k,int):
                            raw.append((None,val,None,cell))
                        else:
                            seen_named=True; raw.append((sstr(k),val,None,cell))
                else:
