        return func.name if func else ''
    def bind_and_call(self,func,raw_args,frame,line,this_obj=None,scope_class=None,called_class=None,method_def=None,display_name=None,is_new=False):
        params=func.params or []
        is_internal=func.is_internal
        display=display_name or self.function_display_name(func,method_def)
        # internal info for counts
        info=None
        if is_internal and method_def is None: info=self.function_info.get(func.name)
        # determine python handler and bypass flags
        pyfn=func.internal_fn if is_internal else None
        no_coerce=bool(getattr(pyfn,'__php_no_coerce__',False)) if callable(pyfn) else False
        no_argcount=bool(getattr(pyfn,'__php_no_argcount__',False)) if callable(pyfn) else False
