        extras=[]
        variadic_param=None; variadic_index=None
        for i,p in enumerate(params):
            if p.variadic: variadic_param=p; variadic_index=i
        pos_index=0
        raw_values_for_frame=[]
        for (rname,rval,rnode,rcell) in raw_args:
            raw_values_for_frame.append(rval)
            if rname is None:
                # positional
                if variadic_index is not None and pos_index>=variadic_index:
                    extras.append((rname,rval,rnode,rcell))
