                else:
                    extras.append((rname,rval,rnode,rcell))
            else:
                # find param
                found=None
                for i,p in enumerate(params):
                    if p.variadic: continue
                    if p.name==rname: found=i; break
                if found is None:
                    if variadic_param is not None:
                        extras.append((rname,rval,rnode,rcell))
                    else:
                        self.throw_error('Error',f'Unknown named parameter ${rname}',frame,line)
                else:
                    if found in bound:
                        self.throw_error('Error',f'Named parameter ${rname} overwrites previous argument',frame,line)
                    bound[found]=(rval,rnode,rcell,True)
                    if found==pos_index: pos_index+=1
