        missing=[]
        for i,p in enumerate(params):
            if p.variadic: continue
            if i not in bound and not p.has_default: missing.append((i,p))
        if missing and not no_argcount:
            # extra trace entry for called function
            extra=self._call_trace_entry(display,func,method_def,raw_args,frame,line)
            if has_named and not is_internal:
