                    msg=f'{display}() expects exactly {total_params} argument{"" if total_params==1 else "s"}, {given_count} given'
                else:
                    msg=f'{display}() expects at least {required_count} argument{"" if required_count==1 else "s"}, {given_count} given'
                self.throw_error('ArgumentCountError',msg,frame,line,extra_trace=extra)
            else:
                if required_count==total_params: exp=f'exactly {required_count} expected'
                else: exp=f'at least {required_count} expected'
