                self.throw_error('ArgumentCountError',msg,frame,line,extra_trace=extra,file_override=func.file,line_override=func.line)
        if is_internal and variadic_param is None and given_count>total_params and not no_argcount:
            extra=self._call_trace_entry(display,func,method_def,raw_args,frame,line)
            if required_count==total_params: msg=f'{display}() expects exactly {total_params} argument{"" if total_params==1 else "s"}, {given_count} given'
            else: msg=f'{display}() expects at most {total_params} argument{"" if total_params==1 else "s"}, {given_count} given'
