    def iterate_items(self,v,frame,line):
        if isinstance(v,PhpArray):
            for k,c in list(v.data.items()): yield (k,c.value,c)
            return
        if isinstance(v,PhpObject):
            if v.class_name.lower()=='generator':
                while self.generator_valid(v,frame,line):
                    yield (self.generator_key(v,frame,line),self.generator_current(v,frame,line),None)
                    self.generator_next(v,frame,line)
                return
            prov=v.internal.get('iterator_items_provider')
            if callable(prov):
                for item in prov(self,v,frame,line): 
                    if len(item)==2: yield (item[0],item[1],None)
                    else: yield item
                return
            if 'array' in v.internal and isinstance(v.internal.get('array'),PhpArray) and v.class_name.lower() in ('arrayobject','arrayiterator','recursivearrayiterator','splfixedarray'):
                for k,c in list(v.internal['array'].data.items()): yield (k,c.value,c)
                return
            if self.find_method(v.class_name,'getIterator') and self.is_a_obj(v,'IteratorAggregate'):
                it=self.call_method_values(v,'getIterator',[],frame,line,internal_system=True)
                yield from self.iterate_items(it,frame,line); return
            if self.find_method(v.class_name,'rewind') and self.is_a_obj(v,'Iterator'):
                self.call_method_values(v,'rewind',[],frame,line,internal_system=True)
                while truthy(self.call_method_values(v,'valid',[],frame,line,internal_system=True)):
                    cur=self.call_method_values(v,'current',[],frame,line,internal_system=True)
                    key=self.call_method_values(v,'key',[],frame,line,internal_system=True) if self.find_method(v.class_name,'key') else 0
                    yield (key,cur,None)
                    self.call_method_values(v,'next',[],frame,line,internal_system=True)
                return
            if self.is_a_obj(v,'Traversable'):
                prov2=self.state.get('iterator_providers',{}).get(v.class_name.lower())
                if prov2:
                    yield from prov2(self,v,frame,line); return
            return
        return
