        if isinstance(v,PhpArray):
            return list((k,c.value,c) for k,c in v.data.items())
        if isinstance(v,PhpObject):
            if self.is_a_obj(v,'Traversable') or v.class_name.lower()=='generator':
                return self.iterate_items(v,frame,line)
            items=[]
            for mk,c in list(v.props.items()):
                disp,vis,priv=self.unmangle_prop_key(mk)
                if c.value is UNINIT: continue
                # visibility: from scope where foreach executed, only accessible props included
                if vis=='private':
                    if not (frame and frame.scope_class and sstr(priv).lower()==frame.scope_class.lower()): continue
                elif vis=='protected':
                    if not (frame and frame.scope_class and (self.is_subclass_of_name(frame.scope_class,v.class_name) or frame.scope_class.lower()==v.class_name.lower())): continue
                items.append((disp,c.value,c))
            return items
        return None
    def create_generator_object(self,func,gen_frame,env,caller_frame,line):
        obj=self.create_object('Generator')
        import queue as _queue
        state={'func':func,'frame':gen_frame,'env':env,'status':'new','thread':None,'to_gen':_queue.Queue(),'to_main':_queue.Queue(),'current':None,'key':None,'return':None,'started':False}
        obj.internal['gen']=state
        gen_frame.generator_state=state
        return obj
    def _generator_thread_run(self,obj):
        state=obj.internal['gen']; func=state['func']; fr=state['frame']
        self.push_frame(fr)
        try:
            if func.is_arrow:
                # arrow functions cannot be generators in PHP, ignore
                ret=self.eval_expr(func.body,fr)
            else:
                ret=None
                try:
                    if func.body is not None: self.exec_block(func.body,fr)
                except ReturnSignal as r: ret=r.value
            state['status']='closed'; state['return']=ret; state['to_main'].put(('return',ret))
        except GeneratorExitInternal:
            state['status']='closed'; state['to_main'].put(('return',None))
        except BaseException as e:
            state['status']='closed'; state['to_main'].put(('exception',e))
        finally:
            self.pop_frame()
    def generator_ensure_current(self,obj,frame,line):
        state=obj.internal.get('gen')
        if state is None: return False
        if state['status']=='new':
            state['status']='running'; state['started']=True
            th=threading.Thread(target=self._generator_thread_run,args=(obj,),daemon=True); state['thread']=th; th.start()
            return self._generator_wait_event(obj,frame,line)
        return state['status']=='yielded'
    def _generator_wait_event(self,obj,frame,line):
        state=obj.internal['gen']; ev=state['to_main'].get()
        if ev[0]=='yield':
            state['status']='yielded'; state['key']=ev[1]; state['current']=ev[2]; return True
        if ev[0]=='return':
            state['status']='closed'; state['return']=ev[1]; state['current']=None; return False
        if ev[0]=='exception':
            state['status']='closed'; raise ev[1]
        return False
