        if not isinstance(obj,PhpObject) or 'gen' not in obj.internal: return False
        return self.generator_ensure_current(obj,frame,line)
    def generator_current(self,obj,frame,line):
        return obj.internal['gen'].get('current') if self.generator_ensure_current(obj,frame,line) else None
    def generator_key(self,obj,frame,line):
        return obj.internal['gen'].get('key') if self.generator_ensure_current(obj,frame,line) else None
    def generator_next(self,obj,frame,line):
        return self.generator_send(obj,None,frame,line)
    def generator_send(self,obj,sendval,frame,line):
        state=obj.internal.get('gen')
        if state is None: return None
        if state['status']=='new':
            if not self.generator_ensure_current(obj,frame,line): return None
        if state['status']!='yielded': return None
        state['status']='running'; state['to_gen'].put(('next',sendval))
        self._generator_wait_event(obj,frame,line)
        return state.get('current')
    def generator_throw(self,obj,exc_obj,frame,line):
        state=obj.internal.get('gen')
        if state is None: return None
        if state['status']=='new':
            # throw into unstarted generator - propagates immediately
            state['status']='closed'; raise PhpThrown(exc_obj)
        if state['status']!='yielded': raise PhpThrown(exc_obj)
        state['status']='running'; state['to_gen'].put(('throw',exc_obj))
        self._generator_wait_event(obj,frame,line); return state.get('current')
    def _yield_point(self,key,value,frame,line):
        state=frame.generator_state
        if state is None:
            return None
        state['to_main'].put(('yield',key,value))
        cmd=state['to_gen'].get()
        if cmd[0]=='close': raise GeneratorExitInternal()
        if cmd[0]=='throw': raise PhpThrown(cmd[1])
        return cmd[1]
    # superglobals
    def get_superglobal_cell(self,name):
        c=self.global_env.vars.get(name)
        if c is not None: return c
        # lazy create
        arr=PhpArray()
        if name=='_ENV':
            if 'E' in str(self.ini_local.get('variables_order','EGPCS')):
                for k,v in os.environb.items(): arr.set(k,v)
        elif name=='_REQUEST':
            order=self.ini_local.get('request_order') or self.ini_local.get('variables_order','EGPCS') or ''
            for ch in str(order):
                src=None
                if ch=='G': src=self.global_env.vars.get('_GET')
                elif ch=='P': src=self.global_env.vars.get('_POST')
                elif ch=='C': src=self.global_env.vars.get('_COOKIE')
                if src and isinstance(src.value,PhpArray):
                    for k,cc in src.value.data.items(): arr.set(k,copy_value(cc.value))
        c=Cell(arr); self.global_env.vars[name]=c
        self.globals_array.data[bstr(name)]=c
        return c

