            names=set()
            pnames={p.name for p in func.params}
            def walk(x):
                if isinstance(x,tuple):
                    if x and x[0]=='var' and len(x)>2 and x[2] not in pnames and x[2]!='this': names.add(x[2])
                    if x and x[0] in ('closure',): return
                    for y in x: walk(y)
                elif isinstance(x,list):
                    for y in x: walk(y)
                elif isinstance(x,dict):
                    for y in x.values(): walk(y)
