    def increment_value(self,v,delta,frame,line,op='++'):
        if isinstance(v,bool):
            self.warn(f'Increment on type bool has no effect, this will change in the next major version of PHP' if op=='++' else f'Decrement on type bool has no effect, this will change in the next major version of PHP',frame,line); return v
        if v is None:
            if delta>0: return 1
            self.warn(b'Decrement on type null has no effect, this will change in the next major version of PHP',frame,line); return None
        if isinstance(v,int): return int_overflow_float(v+delta)
        if isinstance(v,float): return v+delta
        if isinstance(v,bytes):
            if is_numeric_string(v):
                val,_=parse_numeric_string(v); return int_overflow_float(val+delta) if isinstance(val,int) else val+delta
            if delta<0:
                self.deprecated(b'Decrement on non-numeric string has no effect and is deprecated',frame,line); return v
            self.deprecated(b'Increment on non-numeric string is deprecated, use str_increment() instead',frame,line)
            return self.str_increment_bytes(v)
        return v
    def str_increment_bytes(self,s):
        if not s: return b'1'  # PHP ""++ is "1"? handled as numeric? empty not numeric; str_increment requires alnum
        b=bytearray(s); i=len(b)-1; carry=True
        while i>=0 and carry:
            ch=b[i]
            if 48<=ch<=57:
                if ch==57: b[i]=48
                else: b[i]=ch+1; carry=False
            elif 97<=ch<=122:
                if ch==122: b[i]=97
                else: b[i]=ch+1; carry=False
            elif 65<=ch<=90:
                if ch==90: b[i]=65
                else: b[i]=ch+1; carry=False
            else:
                carry=False
            i-=1
        if carry:
            first=s[0:1]
            if first.isdigit(): b=b'1'+bytes(b)
            elif first.islower(): b=b'a'+bytes(b)
            elif first.isupper(): b=b'A'+bytes(b)
            else: b=b'1'+bytes(b) if False else bytes(b)
        return bytes(b)
    def str_decrement_bytes(self,s):
        # Used by str_decrement builtin (not -- operator)
        b=bytearray(s); i=len(b)-1; borrow=True
        while i>=0 and borrow:
            ch=b[i]
            if 48<=ch<=57:
                if ch==48: b[i]=57
                else: b[i]=ch-1; borrow=False
            elif 97<=ch<=122:
                if ch==97: b[i]=122
                else: b[i]=ch-1; borrow=False
            elif 65<=ch<=90:
                if ch==65: b[i]=90
                else: b[i]=ch-1; borrow=False
            else: borrow=False
            i-=1
        if borrow and len(b)>1:
            # e.g. aa -> z, a1? drop leading?
            return bytes(b[1:])
        return bytes(b)
    def unsupported_operands(self,op,lv,rv,frame,line):
        self.throw_error('TypeError',f'Unsupported operand types: {php_type_name(lv)} {op} {php_type_name(rv)}',frame,line)
    def binary_op(self,op,lv,rv,frame,line):
        if lv is NULLSAFE: lv=None
        if rv is NULLSAFE: rv=None
        if op=='.': return self.to_string(lv,frame,line)+self.to_string(rv,frame,line)
        if op=='==': return self.loose_equal(lv,rv,frame,line)
        if op in ('!=','<>'): return not self.loose_equal(lv,rv,frame,line)
        if op=='===': return self.strict_equal(lv,rv)
        if op=='!==': return not self.strict_equal(lv,rv)
        if op=='<=>': return self.compare_loose(lv,rv,frame,line)
        if op in ('<','<=','>','>='):
            if (isinstance(lv,float) and math.isnan(lv)) or (isinstance(rv,float) and math.isnan(rv)): return False
            c=self.compare_loose(lv,rv,frame,line)
            return {'<':c<0,'<=':c<=0,'>':c>0,'>=':c>=0}[op]
        if op=='+' and isinstance(lv,PhpArray) and isinstance(rv,PhpArray):
            out=lv.copy()
            for k,c in rv.data.items():
                if k not in out.data: out.data[k]=c if c.is_ref else Cell(copy_value(c.value))
            out.next_int=max(out.next_int,rv.next_int); return out
        if op in ('&','|','^') and isinstance(lv,bytes) and isinstance(rv,bytes):
            if op=='&':
                n=min(len(lv),len(rv)); return bytes(lv[i]&rv[i] for i in range(n))
            n=max(len(lv),len(rv)); return bytes(((lv[i] if i<len(lv) else 0) | (rv[i] if i<len(rv) else 0)) if op=='|' else ((lv[i] if i<len(lv) else 0) ^ (rv[i] if i<len(rv) else 0)) for i in range(n))
        if op in ('&','|','^','<<','>>'):
