            if a is UNDEF or b is UNDEF: self.unsupported_operands(op,lv,rv,frame,line)
            if op=='&': return wrap64(a&b)
            if op=='|': return wrap64(a|b)
            if op=='^': return wrap64(a^b)
            if op=='<<':
                if b<0: self.throw_error('ArithmeticError','Bit shift by negative number',frame,line)
                if b>=64: return 0
                return wrap64(a<<b)
            if op=='>>':
                if b<0: self.throw_error('ArithmeticError','Bit shift by negative number',frame,line)
                if b>=64: return -1 if a<0 else 0
                return a>>b
