    def file_dir(self,filename):
        if filename in ('Command line code','Standard input code') or "eval()'d code" in filename: return os.getcwd()
        d=os.path.dirname(os.path.abspath(filename)) if filename else os.getcwd()
        return d or '/'
    def run_shell_command(self,cmd,frame,line):
        import subprocess as _sp
        try:
            p=_sp.run(sstr(cmd),shell=True,stdout=_sp.PIPE,stderr=None)
            return p.stdout if p.stdout is not None else None
        except Exception:
            return None
