        if op=='.': return self.to_string(lv,frame,line)+self.to_string(rv,frame,line)
        if op=='==': return self.loose_equal(lv,rv,frame,line)
        if op in ('!=','<>'): return not self.loose_equal(lv,rv,frame,line)
        if op=='===': return self.strict_equal(lv,rv)
        if op=='!==': return not self.strict_equal(lv,rv)
        if op=='<=>': return self.compare_loose(lv,rv,frame,line)
        if op in ('<','<=','>','>='):
            if (isinstance(lv,float) and math.isnan(lv)) or (isinstance(rv,float) and math.isnan(rv)): return False
            c=self.compare_loose(lv,rv,frame,line)
            return {'<':c<0,'<=':c<=0,'>':c>0,'>=':c>=0}[op]
        if op=='+' and isinstance(lv,PhpArray) and isinstance(rv,PhpArray):
            out=lv.copy()
            for k,c in rv.data.items():
                if k not in out.data: out.data[k]=c if c.is_ref else Cell(copy_value(c.value))
            out.next_int=max(out.next_int,rv.next_int); return out
