def render_phpinfo(I,F,flags=-1,include_argv=True):
    if flags is None or flags<0: flags=4294967295
    out='phpinfo()\n'
    if flags & 1:
        out+=render_general(I)
    # config/modules
    if (flags & 4) and (flags & 8):
        out+="\n\n _______________________________________________________________________\n\n\nConfiguration\n\n"+render_modules(I)
    elif flags & 4:
        out+=render_config_core_only(I)
    elif flags & 8:
        out+='\n'+render_modules(I)
    if flags & 16:
        out+=render_environment(I)
    if flags & 32:
        out+=render_variables(I,F)
