        out+='\n'+LICENSE_TEXT
    return bstr(out)
def render_credits(flags=4294967295):
    if flags is None or flags==4294967295 or flags==-1 or flags==0:
        return bstr(DATA['CREDITS'])
    parts=[]
    for bit in (1,2,4,8,16,64):
        if flags & bit:
            txt=DATA['CREDITS_BITS'][str(bit)]
            # each capture starts "PHP Credits\n\n" except fullpage which was just header; for the first, keep as-is, subsequent strip header
            if parts and txt.startswith('PHP Credits\n\n'): txt=txt[len('PHP Credits\n\n'):]
            if txt and not txt.endswith('\n'): txt+='\n'
            parts.append(txt)
    return bstr(''.join(parts) if parts else DATA['CREDITS_BITS'].get('32','PHP Credits\n'))
def render_ri(I,ext_name):
    # case-insensitive matching to module names
    canon=None
    for name in MODULES_ORDER:
        if name.lower()==str(ext_name).lower(): canon=name; break
    if canon is None: return None
    text=RI_DATA[canon]
    lines=[]
    for line in text.splitlines(True):
        stripped=line.rstrip('\n')
        if ' => ' in stripped:
            name=stripped.split(' => ')[0]
            if name in I.ini_local and re.match(r'^[A-Za-z0-9_.\-]+$',name):
                # directive line (3 parts) vs info line (2 parts) - directives in RI have 2 separators
                if stripped.count(' => ')>=2:
                    lines.append(_directive_line(I,name)); continue
                if name=='Default timezone':
                    lines.append(f"Default timezone => {I.state.get('timezone') or 'UTC'}\n"); continue
                if name=='Path to sendmail':
                    lines.append(f"Path to sendmail => {I.ini_local.get('sendmail_path') or ''}\n"); continue
        lines.append(line)
    return bstr(''.join(lines))
