def validate_server_addr(addr):
    if addr is None: return None
    s=str(addr)
    # IPv6 [..]:port
    if s.startswith('['):
        m=re.match(r'^\[(.+)\]:(\d+)$',s)
        if not m: return False
        port=int(m.group(2)); host=m.group(1)
    else:
        if s.count(':')!=1: return False
        host,portstr=s.rsplit(':',1)
        if not host or not portstr.isdigit(): return False
        port=int(portstr)
    if port<0 or port>65535: return False
    return (host,port)

def run_in_thread(fn):
    result={'code':0,'exc':None}
    def target():
        try: result['code']=fn() or 0
        except BaseException as e: result['exc']=e
    th=threading.Thread(target=target); th.start(); th.join()
    if result['exc'] is not None:
        if isinstance(result['exc'],SystemExit): raise result['exc']
        raise result['exc']
    return result['code']

