def _lint_validate(interp,prog,frame):
    # walk scopes for break/continue and goto labels, declare warnings
    def process_block(block,loop_depth,labels,gotos,func_depth=0):
        if not isinstance(block,tuple): return
        stmts=[]
        if block[0]=='block': stmts=block[2]
        else: stmts=[block]
        for stmt in stmts: process_stmt(stmt,loop_depth,labels,gotos)
    def process_stmt(stmt,loop_depth,labels,gotos):
        if not isinstance(stmt,tuple): return
        tag=stmt[0]; line=stmt[1]
        if tag=='label':
            if stmt[2] in labels:
                interp.fatal(f"Cannot redefine label '{stmt[2]}'",frame,line)
            labels.add(stmt[2]); return
        if tag=='goto': gotos.append((stmt[2],line)); return
        if tag in ('break','continue'):
            # level static if literal
            lvl=1
            if stmt[2] and isinstance(stmt[2],tuple) and stmt[2][0]=='int': lvl=stmt[2][2]
            if lvl>loop_depth:
                interp.fatal(f"'{tag}' not in the 'loop' or 'switch' context" if loop_depth==0 else f"Cannot '{tag}' {lvl} levels",frame,line)
            return
        if tag=='declare':
            for nm,val in stmt[2]:
                if nm.lower() not in ('strict_types','ticks','encoding'):
                    interp.warn(f"Unsupported declare '{nm}'",frame,line)
            if stmt[3]: process_block(stmt[3],loop_depth,labels,gotos)
            return
        if tag in ('while','do'):
            # condition expressions may contain closures with own scopes - ignore nested walk in expressions for goto label purposes (expressions cant contain break)
            process_stmt(stmt[3],loop_depth+1,labels,gotos); return
        if tag=='for': process_stmt(stmt[5],loop_depth+1,labels,gotos); return
        if tag=='foreach': process_stmt(stmt[5],loop_depth+1,labels,gotos); return
        if tag=='switch':
            for _,body in stmt[3]:
                for s in body: process_stmt(s,loop_depth+1,labels,gotos)
            return
        if tag=='if':
            for _,b in stmt[2]: process_block(b,loop_depth,labels,gotos)
            if stmt[3]: process_block(stmt[3],loop_depth,labels,gotos)
            return
        if tag=='try':
            process_block(stmt[2],loop_depth,labels,gotos)
            for _,_,b in stmt[3]: process_block(b,loop_depth,labels,gotos)
            if stmt[4]: process_block(stmt[4],loop_depth,labels,gotos)
            return
        if tag=='function_decl':
            fn=stmt[2]
            if fn.body: check_scope(fn.body)
            return
        if tag=='class_decl':
            info=stmt[2]
            for md in info.get('methods') or []:
                if md.func.body: check_scope(md.func.body)
            return
        if isinstance(stmt,tuple):
            for part in stmt[2:]:
                walk_expr(part,labels,gotos)
                if isinstance(part,tuple) and part and part[0]=='block': process_block(part,loop_depth,labels,gotos)
    def walk_expr(x,labels,gotos):
        if isinstance(x,tuple):
            if x and x[0]=='closure':
                fn=x[2]
                if not fn.is_arrow and fn.body: check_scope(fn.body)
                elif fn.is_arrow: walk_expr(fn.body,labels,gotos)
                return
            if x and x[0]=='new_anon':
                for md in x[2].get('methods') or []:
                    if md.func.body: check_scope(md.func.body)
                return
            for y in x[1:]: walk_expr(y,labels,gotos)
        elif isinstance(x,list):
            for y in x: walk_expr(y,labels,gotos)
        elif isinstance(x,dict):
            for y in x.values(): walk_expr(y,labels,gotos)
        elif isinstance(x,MethodDef):
            if x.func.body: check_scope(x.func.body)
    def check_scope(body):
        labels=set(); gotos=[]; process_block(body,0,labels,gotos)
        for lab,line in gotos:
            if lab not in labels: interp.fatal(f"'goto' to undefined label '{lab}'",frame,line)
    check_scope(prog)

def execute_normal_mode(opts):
    # decide source
    is_code=opts['code'] is not None
    is_process=opts['begin'] is not None or opts['run_code'] is not None or opts['run_file'] is not None or opts['end'] is not None
    if is_process:
        return execute_process(opts)
    if is_code:
        def runner():
            interp=make_interp(opts)
            return run_program_once(interp,os.fsencode(opts['code']),'Command line code',['Standard input code']+list(opts['script_args']),'Standard input code','',start_in_php=True,auto=False,direct_code=True)
        return execute_with_repeat(opts,lambda: run_in_thread(runner))
    if opts['file'] is not None:
        file_arg=opts['file']
        def runner():
            data=read_input_file(file_arg)
            canon=os.path.realpath(file_arg) if os.path.exists(file_arg) else file_arg
            interp=make_interp(opts)
            return run_program_once(interp,data,canon,[file_arg]+list(opts['script_args']),file_arg,file_arg,start_in_php=False,auto=True,direct_code=False)
        return execute_with_repeat(opts,lambda: run_in_thread(runner))
    # stdin
    source=sys.stdin.buffer.read()
    def runner():
        interp=make_interp(opts)
        return run_program_once(interp,source,'Standard input code',['Standard input code']+list(opts['script_args']),'Standard input code','',start_in_php=False,auto=True,direct_code=False)
    return execute_with_repeat(opts,lambda: run_in_thread(runner))

def execute_process(opts):
    def run_once():
        interp=make_interp(opts)
        interp.setup_script_superglobals('Standard input code','',['Standard input code']+list(opts['script_args']))
        frame=Frame(env=interp.global_env,file='Standard input code',is_main=True); interp.main_frame=frame; interp.push_frame(frame)
        code=0
        # Preparse F file existence handled outside
        run_prog_template=None
        try:
            if opts['begin'] is not None:
                frame.file='Command line begin code'
                prog=parse_php_source(os.fsencode(opts['begin']),'Command line begin code',True,interp.ini_bool('short_open_tag',True))
                interp.execute_program(prog,frame,'Command line begin code')
            argi=1
            while True:
                raw=sys.stdin.buffer.readline()
                if raw==b'': break
                line=raw.rstrip(b'\n').rstrip(b'\r') if raw.endswith(b'\n') or raw.endswith(b'\r') else raw
                # PHP strips trailing newline and \r? rstrip for line "x\r\n" -> after \n then \r
                line=raw[:-1] if raw.endswith(b'\n') else raw
                if line.endswith(b'\r'): line=line[:-1]
                frame.env.set_value('argn',line); frame.env.set_value('argi',argi); argi+=1
                if opts['run_code'] is not None:
                    frame.file='Command line run code'
                    prog=parse_php_source(os.fsencode(opts['run_code']),'Command line run code',True,interp.ini_bool('short_open_tag',True))
                    interp.execute_program(prog,frame,'Command line run code',is_include=True)
                elif opts['run_file'] is not None:
                    # parse fresh each line like PHP (function redeclare across lines occurs)
                    data=open(opts['run_file'],'rb').read(); canon=os.path.realpath(opts['run_file'])
                    prog=parse_php_source(data,canon,False,interp.ini_bool('short_open_tag',True))
                    interp.execute_program(prog,frame,canon,is_include=True)
            if opts['end'] is not None:
                frame.file='Command line end code'
                prog=parse_php_source(os.fsencode(opts['end']),'Command line end code',True,interp.ini_bool('short_open_tag',True))
                interp.execute_program(prog,frame,'Command line end code')
        except ExitSignal as e:
            code=finish_request(interp,e.code,True); interp.pop_frame(); return code
        except PhpThrown as th:
            code=handle_thrown(interp,th,frame,True); interp.pop_frame(); return code
        except PhpFatal as fat:
            interp.last_error=(1,fat.message,fat.file,fat.line); interp.write(format_fatal(interp,fat)); code=finish_request(interp,255,True); interp.pop_frame(); return code
        except ParseFatal as pf:
            out_bytes(format_parse_error(interp,pf)); code=finish_request(interp,255,True); interp.pop_frame(); return code
        except BaseException:
            import traceback; traceback.print_exc(); interp.pop_frame(); return 255
        code=finish_request(interp,0,True); interp.pop_frame(); return code
    return execute_with_repeat(opts,lambda: run_in_thread(run_once))

