                _execute_auto_file(interp,pre,frame)
        result=interp.execute_program(prog,frame,display_name,is_include=False)
        if auto:
            app=str(interp.ini_local.get('auto_append_file') or '')
            if app:
                _execute_auto_file(interp,app,frame)
    except ExitSignal as e:
        code=finish_request(interp,e.code,True); interp.pop_frame(); return code
    except PhpThrown as th:
        code=handle_thrown(interp,th,frame,direct_code); interp.pop_frame(); return code
    except PhpFatal as fat:
        interp.last_error=(1,fat.message,fat.file,fat.line)
        interp.write(format_fatal(interp,fat)); code=finish_request(interp,255,True); interp.pop_frame(); return code
    except ParseFatal as pf:
        interp.last_error=(4,bstr(pf.message),pf.file,pf.line)
        out_bytes(format_parse_error(interp,pf)); code=finish_request(interp,255,True); interp.pop_frame(); return code
    except RecursionError:
        interp.write(b"\nFatal error: Allowed memory size exhausted in "+bstr(display_name)+b" on line 1\n"); code=finish_request(interp,255,False); interp.pop_frame(); return code
    except BrokenPipeError:
        interp.pop_frame(); return 0
    except BaseException as e:
        # Internal implementation error: surface as fatal for diagnostics in stderr
        import traceback; traceback.print_exc()
        code=255; interp.pop_frame(); return code
    code=finish_request(interp,0,True); interp.pop_frame(); return code

