def format_parse_error(interp,pf):
    if interp and str(interp.ini_local.get('html_errors','0')).strip().lower() in ('1','on','true'):
        msg=_html.escape(str(pf.message)); fn=_html.escape(str(pf.file))
        return bstr(f"<br />\n<b>Parse error</b>:  {msg} in <b>{fn}</b> on line <b>{pf.line}</b><br />\n")
    return b"\nParse error: "+bstr(pf.message)+b" in "+bstr(pf.file)+b" on line "+str(pf.line).encode()+b"\n"
def format_fatal(interp,fat):
    msg=fat.message; file=fat.file or ''; line=fat.line or 0
    trace_str=''
    if interp is not None and fat.trace is not None:
        trace_str=interp.trace_to_string(fat.trace)
    if interp and str(interp.ini_local.get('html_errors','0')).strip().lower() in ('1','on','true'):
        m=_html.escape(sstr(msg)); fn=_html.escape(str(file))
        s=f"<br />\n<b>Fatal error</b>:  {m} in <b>{fn}</b> on line <b>{line}</b><br />\n"
        if trace_str:
            s=f"<br />\n<b>Fatal error</b>:  {m} in <b>{fn}</b> on line <b>{line}</b><br />\nStack trace:\n{_html.escape(trace_str)}\n"
            # PHP html fatal with backtrace format is plain stack after initial line without thrown suffix? Probe for redeclare in html mode later; approximate as above but need include stack in a way closer: replace.
            # Use plain-style fatal body after bold first segment:
            s=f"<br />\n<b>Fatal error</b>:  {m} in {fn} on line {line}\nStack trace:\n{trace_str}\n"
        return bstr(s)
    s=b"\nFatal error: "+msg+b" in "+bstr(file)+b" on line "+str(line).encode()+b"\n"
    if trace_str:
        s+=b"Stack trace:\n"+bstr(trace_str)+b"\n"
    return s

def finish_request(interp,initial_code=0,run_shutdown=True):
    code=initial_code
    if run_shutdown and not interp.state.get('_shutdown_done'):
        try:
            interp.run_shutdown_functions()
        except ExitSignal as e:
            code=e.code
        except PhpThrown as th:
            # exception in shutdown/destructor is fatal
            try:
                interp.write(interp.format_uncaught(th.obj))
            except Exception: pass
            code=255
        except PhpFatal as fat:
            try: interp.write(format_fatal(interp,fat))
            except Exception: pass
            code=255
        except ParseFatal as pf:
            try: interp.write(format_parse_error(interp,pf))
            except Exception: pass
            code=255
    try:
        interp.flush_all_ob()
    except BaseException:
        pass
    return code

def handle_thrown(interp,th,main_frame,direct_code=False):
    obj=th.obj
    # record last error for shutdown error_get_last
    try:
        ex=obj.internal.get('exception',{})
        msg=bstr('Uncaught '+interp.throwable_to_string(obj)+'\n  thrown') if not obj.internal.get('parse_origin') else bstr(obj.internal.get('parse_message',''))
        interp.last_error=(1,msg,sstr(ex.get('file',b'')),ex.get('line',0))
    except Exception: pass
    # custom exception handler (not for direct -r eval code)
    if (not direct_code) and interp.exception_handler_stack:
        handler=interp.exception_handler_stack[-1]
        try:
            interp.call_callable_values(handler,[obj],main_frame,1)
            return finish_request(interp,0,True)
        except PhpThrown as th2:
            try: interp.write(interp.format_uncaught(th2.obj))
            except Exception: pass
            return finish_request(interp,255,True)
        except ExitSignal as e:
            return finish_request(interp,e.code,True)
    interp.write(interp.format_uncaught(obj))
    return finish_request(interp,255,True)

def run_program_once(interp,source,display_name,script_argv,script_server_name,script_server_filename,start_in_php=False,auto=True,direct_code=False):
