        # Internal implementation error: surface as fatal for diagnostics in stderr
        import traceback; traceback.print_exc()
        code=255; interp.pop_frame(); return code
    code=finish_request(interp,0,True); interp.pop_frame(); return code

def _execute_auto_file(interp,path,frame):
    found,real=interp.resolve_include_path(bstr(path),frame)
    if not found:
        saved=frame.file; frame.file='Unknown'
        interp.warn('Unknown: Failed to open stream: No such file or directory',frame,0)
        frame.file=saved
        raise PhpFatal(f"Failed opening required '{path}' (include_path='{interp.ini_local.get('include_path','.:')}')",'Unknown',0,trace=[])
    data=open(found,'rb').read(); realpath=os.path.realpath(found)
    prog=parse_php_source(data,realpath,False,interp.ini_bool('short_open_tag',True))
    if realpath not in interp.included_files: interp.included_files.append(realpath)
    return interp.execute_program(prog,frame,realpath,is_include=True)

def read_input_file(path_str):
    if os.path.isdir(path_str): return b''
    return open(path_str,'rb').read()
def input_file_exists(path_str):
    return os.path.exists(path_str)

def execute_with_repeat(opts,runner):
    raw=opts.get('repeat')
    if raw is None: return runner()
    # C atoi
    m=re.match(r'\s*([+-]?\d+)',str(raw)); cnt=int(m.group(1)) if m else 0
    if cnt==1: return runner()
    if cnt>1:
        out_bytes(b'Executing for the first time...\n')
        code=runner()
        if code!=0: return code
        for _ in range(cnt-1):
            out_bytes(b'Finished execution, repeating...\n')
            code=runner()
            if code!=0: return code
        return code
    # <=0 loops (PHP underflow) - mirror by looping
    out_bytes(b'Executing for the first time...\n')
    while True:
        code=runner()
        if code!=0: return code
        out_bytes(b'Finished execution, repeating...\n')

