        runset=set(); interp.file_runs.append(runset)
        try: interp._predeclare(prog[2],frame,runset)
        finally: interp.file_runs.pop()
    except PhpFatal as fat:
        interp.write(format_fatal(interp,fat)); out_bytes(b"Errors parsing "+bstr(display)+b"\n"); interp.pop_frame(); return 255
    except PhpThrown as th:
