        interp.write(interp.format_uncaught(th.obj)); out_bytes(b"Errors parsing "+bstr(display)+b"\n"); interp.pop_frame(); return 255
    interp.pop_frame()
    out_bytes(b"No syntax errors detected in "+bstr(display)+b"\n")
