def _404_body(path):
    esc=(path.decode('utf-8','surrogateescape') if isinstance(path,bytes) else str(path)).replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
    return (f'<!doctype html><html><head><meta name="viewport" content="width=device-width, initial-scale=1"><title>404 Not Found</title><style>\nbody {{ background-color: #fcfcfc; color: #333333; margin: 0; padding:0; }}\nh1 {{ font-size: 1.5em; font-weight: normal; background-color: #9999cc; min-height:2em; line-height:2em; border-bottom: 1px inset black; margin: 0; }}\nh1, p {{ padding-left: 10px; }}\ncode.url {{ background-color: #eeeeee; font-family:monospace; padding:0 2px;}}\n</style>\n</head><body><h1>Not Found</h1><p>The requested resource <code class="url">{esc}</code> was not found on this server.</p></body></html>').encode()

def run_server(opts):
    host,port=opts.get('_server_parsed') or ('127.0.0.1',8000)
    docroot_arg=opts.get('docroot')
    initial_cwd=os.getcwd()
    docroot=os.path.realpath(docroot_arg) if docroot_arg else initial_cwd
    if docroot_arg and not os.path.isdir(docroot):
        _err(f'Directory {docroot_arg} does not exist.\n'); return 1
    router=opts.get('router')
    if router is None and opts.get('file') is not None and opts.get('file_via')=='bare':
        router=opts.get('file')
    router_fs=os.path.realpath(router) if router else None
    # Get address info
    try:
        infos=socket.getaddrinfo(host if host not in ('','0') else None,port,socket.AF_UNSPEC,socket.SOCK_STREAM,0,socket.AI_PASSIVE)
    except Exception as e:
        _err(f"Invalid address: {opts.get('server')}\n"); return 1
    if not infos:
        _err(f"Invalid address: {opts.get('server')}\n"); return 1
    family,typ,proto,canon,addr=infos[0]
    srv=socket.socket(family,typ,proto)
    try:
        srv.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1)
        srv.bind(addr); srv.listen(128)
    except Exception as e:
        _err(f'Failed to listen on {host}:{port} (reason: {e.strerror if hasattr(e,"strerror") and e.strerror else e})\n'); return 1
    actual_port=srv.getsockname()[1]
    display_host=f'[{host}]' if ':' in str(host) and not str(host).startswith('[') else str(host)
    authority=f'{display_host}:{actual_port}'.encode()
    startup_host=str(opts.get('server'))
    if port==0:
        # replace trailing :0
        startup_host=re.sub(r':0$',f':{actual_port}',startup_host)
    _log(f'PHP 8.6.0-dev Development Server (http://{startup_host}) started')
    # Determine base ini values for response headers with dummy interp lazily per request if needed
    while True:
        try:
            conn,remote=srv.accept()
        except KeyboardInterrupt:
            break
        except Exception:
            break
        fmt_remote=f'{remote[0]}:{remote[1]}' if isinstance(remote,tuple) else str(remote)
        _log(f'{fmt_remote} Accepted')
        request_time=time.time()
        try:
            response,_logline=_handle_connection(conn,remote,opts,docroot,router_fs,authority,actual_port,host)
        except BaseException:
            import traceback; traceback.print_exc(); response=None; _logline=None
        if _logline:
            _log(_logline)
        try: conn.close()
        except Exception: pass
        _log(f'{fmt_remote} Closing')
    return 0

def _handle_connection(conn,remote,opts,docroot,router_fs,authority,actual_port,bind_host):
